local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["zone:tirisfal"] = {n="Tirisfal Glades",s="Tirisfal Glades är Lordaerons hemsökta nordliga område och utgör nu Lady Sylvanas Windrunners och de Förkastades kärnland. Under fördärvade himlar och ruttnande grenar ligger fallna herrgårdar, slumrande kryptor och den väldiga underjordiska huvudstaden Undercity. Omgivet av tanklösa plågoandar och fanatiska Scarlet-korsfarare är detta ett farligt rike där de viljestarka odöda kämpar för sin överlevnad.",h="Tirisfal Glades är Lordaerons hemsökta nordliga område och utgör nu Lady Sylvanas Windrunners och de...",kw={"agamand","balnir","brill","deathknell","förkastade","glades","lordaeron","scarlet crusade","sylvanas","tirisfal","undercity"},ang={["class:Priest"]="Heliga historiska platser som Faol's Rest, ärkebiskop Alonsus Faols grav och Silver Hands grundares sista viloplats, ligger här. De har förvridits av döden och är omstridda mellan fanatiker och skuggpräster.",["faction:Alliance"]="För Alliansens överlevande folk är Tirisfal ett tragiskt minnesmärke över Lordaerons fall, fyllt av vanhelgade gravar efter forna bröder och systrar i tron.",["faction:Horde"]="Tirisfal är Hordens livsviktiga fäste i norra Eastern Kingdoms. Därifrån hålls de diplomatiska banden med de Förkastade vid liv, samtidigt som mänskliga extremister och Scourge hålls stången.",["race:Undead"]="Det här är ditt förfäders hemland två gånger om: kungariket du byggde när du levde och den osäkra fristad du måste försvara som odöd under Lady Sylvanas."},sec={{t="Ett land i skymning",b="Tirisfal Glades var en gång mänsklighetens bördiga vagga, men har vissnat under Lich Kings pestförbannelse. Solen tränger sällan igenom det grumliga dunklet och lägger ett evigt, sjukligt blekt sken över döende skogar, försummade pumpaland och kalla kustkullar. De gamla gårdarna Agamand Mills och Balnir Farmstead står fortfarande kvar, men deras forna herrar har till största delen hamnat i massgravar eller återuppstått som rastlösa döda. Trots förödelsen genomsyras landsbygden av en mörk motståndskraft, med städer som Brill och den avskilda fristaden Deathknell som fästen, där nyväckta Förkastade lär sig uthärda sitt andra liv."},{t="Krig på två fronter",b="Lady Sylvanas gör anspråk på herraväldet över området från de underjordiska Ruins of Lordaeron, men de Förkastade är fortfarande trängda från alla håll. Kvarvarande trälar från Scourge härjar fortfarande i hålor, på fält och i förfallna kryptor, helt underställda Northrends frusna tron. I öster har den fanatiska Scarlet Crusade gjort norra Tirisfal till sitt främsta fäste och verkar från Scarlet Monastery. De är hängivna åt att utrota alla odöda varelser, vare sig de är levande eller döda, och deras utposter och patruller utkämpar ständigt gerillakrig mot Förkastades spejare och civila resenärer."},{t="Ekon från det forntida förflutna",b="Långt innan de mänskliga rikena krönte sina första monarker bar Glades på ett uråldrigt arv. Högborne alvflyktingar försökte under en kort tid slå sig ner i skogarna, men skuggkrafter djupt under jorden började driva dem till vansinne och fick dem att vandra norrut. Under senare århundraden valde den hemliga dödliga sammanslutningen Council of Tirisfal dessa skuggiga dungar för att ge ensamma väktare kraft och skydda Azeroth från demoniska intrång."}},faq={{q="Varför är himlen grön och marken ruttnar?",a="Under det tredje kriget spred prins Arthas och Scourge De odödas pest över kungariket Lordaeron. Den magiska farsoten förgiftade inte bara befolkningen utan även jorden, träden och vattnet, och lämnade Glades i ett evigt tillstånd av kusligt, sjukligt förfall.",al={"varför är tirisfal fördärvat","vad hände med tirisfal","varför håller tirisfal på att dö"}},{q="Vad är skillnaden mellan de Förkastade och Scourge här?",a="De Förkastade är odöda som bröt sig fria från Lich Kings telepatiska herravälde efter slaget vid Mount Hyjal och valde att följa Lady Sylvanas Windrunner av egen fri vilja. Scourge som strövar kring gårdarna och ruinerna förblir tanklösa slavar, bundna till Lich Kings befallningar.",al={"förkastade jämfört med scourge","varför anfaller zombier odöda","är alla odöda onda"}},{q="Vilka är de rödpansrade soldaterna som anfaller resenärer?",a="De tillhör Scarlet Crusade, en kompromisslös utbrytarorden bestående av forna paladiner från Silver Hand och överlevare. De är övertygade om att alla odöda är oförbätterliga styggelser som måste renas med svärd och eld, och avrättar med fanatiskt hat både tanklösa trälar och viljestarka Förkastade.",al={"scarlet crusade","röda människor","människor från klostret"}},{q="Varifrån kommer namnet Tirisfal?",a="Namnet är äldre än alla mänskliga riken, och dess verkliga ursprung har gått förlorat i historien. Det är mest känt genom Council of Tirisfal, den hemliga magiorden som gav väktarna kraft att skydda Azeroth från demoner.",al={"tirisfals betydelse","tirisfals ursprung"}},{q="Var börjar nyväckta Förkastade sin färd?",a="Nyväckta Förkastade kommer ut ur kryptorna i Shadow Grave i Deathknell, en avskild stad i sydvästra Tirisfal. Där bedömer administratörer och bödlar om de återuppståndna döda har det förstånd och den lojalitet som krävs för att tjäna den Mörka Damen.",al={"odödas startområde","var ligger deathknell","de förkastades startområde"}},{q="Hur lämnar resenärer Tirisfal för andra kontinenter?",a="Ett stort zeppelintorn som drivs av gobliner står på sluttningen söder om Brill, precis utanför Ruins of Lordaeron. Luftskeppen erbjuder direkt och regelbunden färd över haven till Orgrimmar i Kalimdor och Grom'gol Base Camp i Stranglethorn Vale.",al={"zeppeliner i tirisfal","hur tar man sig till orgrimmar","hur tar man sig till stranglethorn"}}},fx={["6c272224"]={q="Vad är Tirisfal Glades?",a="Tirisfal Glades är de Förfallnas kärnland vid Lordaerons norra kust. Området var en gång den fredliga, bördiga kärnan i ett stolt mänskligt kungarike, men härjades av Scourges odödlighetsplåga under det tredje kriget. I dag täcker fördärvade skogar och ett ständigt grönt dunkel kullarna, omgivna av ruinerna av Lordaerons huvudstad, fientliga fanatiker, vilda bestar och kvarvarande odöda.",al={"vad är tirisfal","berätta om tirisfal glades","lore om tirisfal"}},["342b65f9"]={q="Har det här alltid varit de odödas land?",a="Nej. I tusentals år var Tirisfal den mänskliga civilisationens vagga och det blomstrande hjärtat i kungariket Lordaeron. Fredliga gårdar, välmående kvarnar och små byar frodades under kung Terenas Menethil. Den tiden fick ett våldsamt slut under det tredje kriget, när prins Arthas och Cult of the Damned drog fram med pesten och förvandlade invånarna till odöda slavar. Sylvanas befriade dem sedan.",al={"var tirisfal alltid odött","vilka bodde här tidigare","tirisfal före pesten"}},["4790468d"]={q="Vilka bor i eller styr Tirisfal Glades?",a="De Förfallna gör anspråk på Tirisfal Glades under drottning Sylvanas Windrunners styre från Undercity. Men deras grepp om området utmanas ständigt. Fanatiska Scarlet Crusade håller befästningar och sitt stora kloster i nordöst, medan tanklösa Scourge stryker omkring på övergivna gårdar. Vid den östra gränsen, vid The Bulwark, samverkar de Förfallna med Argent Dawn för att hålla Plaguelands fasor i schack.",al={"vem styr tirisfal","vem kontrollerar tirisfal glades","fraktioner i tirisfal"}},["97ffdb73"]={q="Är Tirisfal Glades farligt?",a="Extremt farligt. Utanför de Förfallnas utposters murar möter du kvarvarande tanklösa Scourge, vilda gnoller, jättespindlar och aggressiva djur som smittats av pesten. Ännu värre är fanatikerna i Scarlet Crusade, som avrättar alla odöda de får syn på. Långt österut ligger Western Plaguelands, där monster som är långt dödligare än allt i Tirisfal sliter sönder den oförsiktige.",al={"hur farligt är tirisfal","hot i tirisfal","är det tryggt här"}},["30e6283a"]={q="Vem bestämmer i Brill?",a="Magistrate Sevren sköter Brills civila förvaltning och ansvarar för stadens återuppbyggnad och invånarnas dagliga överlevnad. Den militära ledningen och de taktiska operationerna, särskilt kampanjen mot den närliggande Scarlet Crusade, leds av Executor Zygand.",al={"ledare i brill","vem leder brill","ansvarig i brill"}},["3fc3649e"]={q="Vem rapporterar Magistrate Sevren till?",a="Sevren tjänar den Mörka Damen, drottning Sylvanas Windrunner. Som magistrat i Brill företräder han de Förfallnas kronas civila myndighet i regionen och samarbetar direkt med kungliga exekutorer och Royal Apothecary Society i Undercity.",al={"sevrens chef","vem rapporterar sevren till","ledningskedjan i brill"}},["381a9b46"]={q="Var finns bansheedrottningen?",a="Lady Sylvanas Windrunner bor i Royal Quarter i Undercity, djupt under ruinerna av Capital City, strax söder om Brill. Från sin tronhall leder hon de Förfallna i kriget mot Scourge och Scarlet Crusade.",al={"var är sylvanas","hitta sylvanas","bansheedrottningens plats"}},e7993821={q="Vad är Brill?",a="Brill är de Förfallnas främsta stad i centrala Tirisfal Glades, vid vägkorsningen norr om Capital City. Det var en gång en levande bosättning under Barov-ätten. Efter det tredje kriget byggdes den upp för att ge nyvaknade odöda en plats för vila, handel och organisering innan de ger sig ut i världen.",al={"om brill","vad är brill för slags stad","lore om brill"}},["529e09c8"]={q="Bodde det levande människor här tidigare?",a="Ja. Brill var en gång ett stillsamt mänskligt samhälle i kungariket Lordaeron. Orten blev centrum för tidiga pestexperiment som Kel'Thuzad låg bakom. De ledde till massdöd och väldiga gemensamma gravar, långt innan prins Arthas kom dit för att undersöka saken.",al={"bodde människor i brill","brills historia som levande stad","vilka bodde i brill"}},["7b7ff5e2"]={q="Vad är Gallows' End Tavern?",a="Gallows' End Tavern är Brills centrala samlingslokal och värdshus. Där erbjuds skydd, vidriga drycker och en stunds vila från de dystra gläntorna utanför. I de mörkare hörnen håller de Förfallna fångade fiender, som fanatiker från Scarlet Crusade, för skumma experiment med alkemistblandningar.",al={"gallows' end tavern","värdshus i brill","vad är gallows' end"}},["0d8014ee"]={q="Vad är grejen med Agamand Mills?",a="Agamand Mills var en gång den rikaste och mest produktiva jordbruksegendomen i Tirisfal Glades, känd för sitt mjöl och spannmål. När pesten slog till blev hela området överrunnet och en massaker följde. I dag står där en ruttnande ruin full av väderkvarnar och kvarvarande odöda från Scourge.",al={"lore om agamand mills","vad hände med agamand mills","agamand mills"}},["001d4abe"]={q="Vilka var Agamand-ätten?",a="Agamand-ätten var en adlig och välbärgad mänsklig familj som byggde ut de vidsträckta kvarnarna och ägde mark runt om i Tirisfal, bland annat i Brill. Under det tredje kriget kunde deras rikedom inte rädda dem. Familjen föll för Scourge, och dess återuppväckta patriarker hemsöker fortfarande egendomen.",al={"agamand-familjen","vilka bodde vid agamand mills","agamand-ätten"}},eeb96a2c={q="Varför är de fientliga mot oss när de också är odöda?",a="De odöda som hemsöker Agamand Mills återfick aldrig sin fria vilja. Till skillnad från de Förfallna, som slet sig loss från Lich Kings mentala grepp, förblir de här varelserna förslavade som tanklösa Scourge-trälar. De tvingas förgöra alla levande eller upproriska döda som inkräktar på deras område.",al={"varför anfaller agamand oss","varför är agamands odöda fientliga","varför slåss odöda mot varandra"}},a357af07={q="Vart leder vägen efter Tirisfal?",a="De flesta Förfallna reser söderut genom bergspasset till Silverpine Forest för att hjälpa till att säkra den södra gränsen och bekämpa agenter från Dalaran och gnoller från Rot Hide. Luftskeppen söder om Brill tar dig också till Orgrimmar eller Grom'gol Base Camp på andra sidan havet.",al={"vart efter tirisfal","nästa område efter tirisfal","efter tirisfal glades"}},["50336b90"]={q="Vad är Undercity?",a="Undercity är de Förfallnas vidsträckta underjordiska huvudstad, byggd i de gamla kloakerna, gravkamrarna och katakomberna under de förstörda Ruins of Lordaeron. Staden fungerar som drottning Sylvanas fäste och som ledningscentral för de Förfallnas verksamhet i hela Azeroth.",al={"vad är undercity","lore om undercity","om undercity"}},ddddba9f={q="Är Silverpine nästa gräns?",a="Ja. Om du följer vägen söderut från Tirisfal kommer du direkt till Silverpine Forest. Det är den naturliga fortsättningen på din tjänst hos Forsaken, där du möter det växande hotet längs Lordaerons södra gränser.",al={"silverpine härnäst","ska jag till silverpine härnäst","silverpines gräns"}},["789ead4d"]={q="Hur hamnade jag i Tirisfal Glades?",a="Om du nyligen återuppstått som Forsaken dog du när Scourge föll över Lordaeron och begravdes här. När Lich Kings grepp bröts återfick du din fria vilja och klöste dig upp ur graven i den avskilda dalen Deathknell. Om du tillhör någon av de andra Horde-nationerna kom du troligen hit via zeppelintornen mellan Brill och Undercity, som förbinder detta fördärvade rike direkt med Orgrimmar och Grom'gol Base Camp.",al={"hur hamnade jag här","hur kom jag till tirisfal glades","hur kom jag hit"}},["89135166"]={q="Vad förväntas jag göra i Tirisfal Glades?",a="Ditt mål är att hjälpa Forsaken att säkra sitt osäkra grepp om Lordaerons fördärvade hjärtland. Från kryptorna i Deathknell ska du ta dig mot staden Brill och rena övergivna gårdar från den själlösa Scourge, slå ut fanatiska Scarlet Crusade-anhängare som tränger in från norr och gallra bland de pestsmittade bestarna i de ruttnande skogarna. På så sätt visar du Lady Sylvanas vad du går för och förbereder dig på att tjäna hennes växande kungarike under ruinerna av Capital City.",al={"vad ska jag göra här","varför är jag i tirisfal","vad är mitt mål här"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Undercity",s="Djupt under de krossade ruinerna av Lordaerons huvudstad ligger Undercity, de Förkastades mörka fäste. Det höggs ursprungligen ut ur uråldriga kungliga kryptor och fängelsehålor av Scourge. Lady Sylvanas Windrunner intog det och gjorde det till en ointaglig underjordisk fristad. I dag är det maktens säte för de Förkastade och Hordens viktiga bastion i norra Eastern Kingdoms.",h="Djupt under de krossade ruinerna av Lordaerons huvudstad ligger Undercity, de Förkastades mörka fäste.",kw={"apothecarium","arthas","de förkastade","lordaeron","scourge","sylvanas","terenas","tirisfal","undercity","varimathras"},ang={["faction:Horde"]="Som Hordens främsta fäste i Eastern Kingdoms säkrar Undercity zeppelinförbindelser direkt till Durotar och Grom'gol Base Camp.",["race:Human"]="Under jorden i ditt fallna förfädersrike ligger en mörk förvrängning av Lordaerons kungliga kryptor, där dina forna fränder nu vandrar som lik.",["race:Orc"]="Djupt inne i dessa fängelsehålor satt den legendariska krigshövdingen Orgrim Doomhammer en gång fängslad av Lordaerons allians, innan han gjorde sin historiska flykt.",["race:Undead"]="Undercity är din suveräna fristad och ditt hemland, uthugget av dina egna händer efter att du bröt Lich Kings järngrepp om ditt sinne."},sec={{t="Från kungliga kryptor till Scourges fäste",b="Långt innan pesten svepte över Lordaeron kallades katakomberna, fängelsehålorna och kloakerna under palatset tillsammans för Undercity. Där fanns adelns gravar, rikets djupaste fängelser, där den tidigare krigshövdingen Orgrim Doomhammer en gång hölls fången innan han flydde, och rikets fattigaste invånare. När Arthas Menethil mördade kung Terenas och ödelade huvudstaden år 20 efter Dark Portal beordrade prinsen sina odöda tjänare att gräva ut och utvidga gångarna under jord till ett befäst säte för Scourges styre."},{t="De Förkastades uppgång",b="Scourge hann aldrig färdigställa sin mörka huvudstad. När Lich Kings krafter försvagades efter slaget vid Mount Hyjal bröt Lady Sylvanas Windrunner sig fri från det kollektiva medvetandet och tog tusentals odöda med sig. Hon lockade Arthas i ett bakhåll och drev honom tillbaka till Northrend. Efter ett skoningslöst inbördeskrig på tre fronter mot resterna av Scourge, dreadlords och mänskligt motstånd tog Sylvanas katakomberna som inte var färdigbyggda. Hon gav sitt folk namnet de Förkastade och ledde under flera år arbetet med att färdigställa den vidsträckta underjordiska staden."},{t="De fördömdas arkitektur",b="Undercity är byggt i koncentriska ringar som är indelade i olika kvarter. I dess hjärta ligger Trade Quarter, som är förbundet med palatsruinerna ovanför genom stora hissar. Runt det ligger War Quarter, Rogues' Quarter, Magic Quarter och det giftiga Apothecarium, där Royal Apothecary Society brygger våldsamma farsoter i kanaler fyllda av grönt slem. Ännu längre in ligger Royal Quarter, där Banshee Queen håller hov tillsammans med sin dreadlordbefälhavare Varimathras. Där vaktas de av legioner av resliga styggelser."}},faq={{q="Vad var Undercity innan de odöda tog över?",a="Under Lordaerons palats låg de uråldriga kryptorna för mänskliga kungligheter, tillsammans med stadens fängelsekomplex och vidsträckta kloaksystem. Där fanns krigsfångar, däribland Orgrim Doomhammer, och utblottade invånare som levde i skuggorna under jord. Efter att ha plundrat huvudstaden började prins Arthas göra katakomberna till en fästning för Scourge, innan Sylvanas intog dem.",al={"undercitys ursprung","vad var undercity från början","lordaerons kloakers historia"}},{q="Varför är staden byggd under jord i stället för ovan jord?",a="Lordaerons stad ovan jord ödelades fullständigt under det tredje kriget. Den var därför svår att försvara mot Scarlet Crusade, Scourges styrkor och överlevande från alliansen. Gångarna under jord erbjöd naturliga försvarsverk, trånga passager och skydd från insyn, vilket lät de Förkastade slutföra Scourges ursprungliga byggnadsarbete och frodas obemärkta.",al={"varför bo under jord","varför återuppbygger man inte lordaeron","varför ligger undercity under ruinerna"}},{q="Vem styr över Undercity?",a="Staden styrs av Lady Sylvanas Windrunner, Banshee Queen och de Förkastades drottning. Hon regerar från Royal Quarter, vaktad av de Förkastades kungliga väktare och sin underkuvade dreadlordlöjtnant Varimathras.",al={"vem leder undercity","undercitys härskare","vem styr undercity"}},{q="Vad föreställer kung Terenas minnesmärke i ruinerna ovanför?",a="Ovanför stadens främsta hissar står ett stenmonument över den mördade kung Terenas Menethil II. Hans kropp finns inte där, eftersom den kremerades och askan kastades bort under Kel'Thuzads återuppståndelse. Överlevande människor från alliansen högg modigt ut monumentet bland ruinerna, så att minnet av Lordaerons sista sanna kung skulle leva vidare.",al={"kung terenas grav","lordaerons tronrum grav","vem byggde graven ovanför undercity"}},{q="Vad är det för märkliga ljud i Lordaerons tronrum?",a="I det förstörda tronrummet ovanför Undercitys hissar dröjer det förflutnas spöklika ekon kvar. Besökare som står i mitten kan höra svaga ljud från vålnader: festklockorna och rosenbladen när Arthas återvände, profeten Medivhs varningsord och det sista samtalet mellan kung Terenas och hans fadersmördande son.",al={"spökljud i tronrummet","viskningar i tronrummet","röster i lordaerons tronrum"}},{q="Varför tillåter de Förkastade andra medlemmar av Horden här?",a="De Förkastade bildade en allians av nödvändighet med krigshövding Thralls Horde för att överleva, omringade som de är av fientliga fanatiker från Scarlet Crusade och legioner från Scourge. De levande raserna i Horden har svårt att uthärda de giftiga ångorna och de alkemiska floderna, men sändebud och resande släpps in för att främja diplomatiska och militära band.",al={"varför finns orcher i undercity","horden i undercity","varför tillhör undercity horden"}}},fx={a590d153={q="Vad är Undercity?",a="Undercity är Forsakens underjordiska huvudstad, byggd direkt under de krossade ruinerna av Capital City i Tirisfal Glades. Staden höggs ut ur gamla kungliga kryptor, kloaker och katakomber. Prince Arthas byggde ut den till ett fäste för Scourge innan Lady Sylvanas Windrunner och hennes avfälliga odöda tog över under inbördeskriget. I dag är den en befäst fristad för odöda med fri vilja, genomkorsad av giftigt slam och noggrant bevakad mot alla levande inkräktare.",al={"vad är undercity","berätta om undercity","undercitys historia"}},c51b16b2={q="Vad hände med Lordaerons gamle kung?",a="King Terenas Menethil II mördades i tronsalen direkt ovanför staden av sin egen son, Prince Arthas. Efter att ha återvänt från Northrend, förvriden av runklingan Frostmourne, slog Arthas ner sin far och släppte lös Scourge över kungariket. Dödsriddaren stal senare Terenas aska för att återuppväcka Kel'Thuzad. Kvar blev bara minnesstenen och det intorkade blodspår som du fortfarande kan se nära den förstörda tronen.",al={"king terenas öde","vad hände med king terenas","vem dödade king terenas"}},c11144c7={q="Vem var Arthas?",a="Arthas Menethil var kronprins av Lordaeron och en hyllad paladin i Silver Hand. I sin desperation att stoppa undeath-pesten som svepte över hans hemland blev hans korståg hänsynslöst och fanatiskt. I Northrend tog han den förbannade runklingan Frostmourne, som slukade hans själ och gjorde honom till Lich Kings fruktade förkämpe. Han återvände hem och slaktade sin far, jämnade Lordaeron med marken och reste till slut tillbaka norrut för att förena sig med Frozen Throne.",al={"vem är arthas","prince arthas historia","arthas menethil"}},["7f6bbd49"]={q="Vem är Sylvanas Windrunner?",a="Lady Sylvanas Windrunner var en gång Silvermoons tappra ranger-general och försvarade Quel'Thalas mot Scourge under det tredje kriget. När hon föll slet Arthas hennes själ ur kroppen och förvandlade henne till en banshee för att plåga henne. När Lich Kings grepp försvagades bröt hon sig fri, återtog sin fysiska form och samlade andra självständiga odöda till Forsaken. Nu härskar hon som deras Banshee Queen från Royal Quarter.",al={"vem är banshee queen","sylvanas historia","vem är sylvanas"}},["2a8de90f"]={q="Varför kallas Sylvanas Dark Lady?",a="Forsaken hedrar Sylvanas som Dark Lady eftersom hon befriade dem från Lich Kings själlösa träldom och gav dem skydd när resten av Azeroth ville utrota dem helt. Titeln används tillsammans med Banshee Queen och speglar både hennes skuggfyllda makt över döden och hennes odöda undersåtars glödande, orubbliga hängivenhet.",al={"varför dark lady","sylvanas titel dark lady","vad betyder dark lady"}},["84f18f47"]={q="Varför tillhör Forsaken Horde?",a="Omgivna av fientliga Scarlet Crusade-anhängare, obevekliga Scourge-styrkor och hämndlystna rester av Alliance kunde Forsaken inte överleva ensamma i Lordaeron. Lady Sylvanas sträckte sig över havet till Warchief Thrall och slöt en pragmatisk allians av ömsesidig nytta. Horde fick ett viktigt militärt fäste i Eastern Kingdoms, medan Forsaken säkrade nödvändiga förstärkningar och politisk legitimitet i sin kamp för överlevnad.",al={"varför forsaken är med i horde","odöda går med i horde","forsaken, horde och alliance"}},["71200045"]={q="Vad är Scourge, och finns de fortfarande i närheten?",a="Scourge är den väldiga, glupska armé av själlösa odöda som skapades av Burning Legion och styrs av Lich King från Northrend. Forsaken ryckte Undercity och Tirisfal ur deras grepp, men Scourge är fortfarande ett omedelbart, dödligt hot. Deras legioner kväver fortfarande de närliggande Plaguelands under Kel'Thuzads befäl och hemsöker övergivna gårdar och kryptor i hela Tirisfal Glades.",al={"finns scourge i närheten","vad är scourge","scourge i lordaeron"}},["501548ab"]={q="Var är Lich King nu?",a="Lich King håller till på Frozen Throne i Northrends avlägsna, iskalla ödemarker. Efter inbördeskriget i Plaguelands flydde Prince Arthas från Lordaeron för att skydda sin försvagade mästare. Han besteg glaciären och förenade deras väsen till en enda skräckinjagande varelse. Från det arktiska fästet vakar hans iskalla blick fortfarande över Azeroth.",al={"var är lich king","lich kings plats","var är arthas nu"}},["4cc7f971"]={q="Vilka är Scarlet Crusade?",a="Scarlet Crusade är en fanatisk orden av mänskliga fanatiker, född ur ruinerna av Lordaerons försvar. Förblindade av sitt rättfärdiga hat mot odöda skiljer de inte mellan själlösa Scourge och Forsaken med fri vilja. De ser alla som smittats av undeath, och alla levande främlingar som tolererar dem, som avskyvärda missfoster som bara förtjänar bålet. Deras främsta fäste i Tirisfal är Scarlet Monastery.",al={"vilka är scarlet crusade","scarlet crusade-anhängare","scarlet crusades historia"}},["271820ed"]={q="Är Undercity farligt?",a="Det är oerhört farligt, särskilt för levande. Kanaler med rått alkemiskt avfall och giftigt slam löper genom stadens gator. De fyller de väldiga salarna med giftiga ångor som gör det farligt att andas för besökare av kött och blod. Under de stenlagda kvarteren ligger kloaker fulla av ohyra, och ännu djupare pågår hemliga experiment där mörk alkemi och hänsynslösa mord planeras dagligen.",al={"är undercity säkert","faror i undercity","undercitys faror"}},["2539a3c3"]={q="Hur hamnade jag i Undercity?",a="Som Forsaken ledde din väg naturligt hit efter att du vaknat till liv i Deathknell och visat din lojalitet genom Tirisfal Glades. Du följde vägarna förbi Brill och tog dig ner under de krossade ruinerna av Capital City. Om du kommer från Kalimdor eller avlägsna länder anlände du troligen med en Horde-zeppelin som lade till vid tornen utanför huvudstaden, eller så vandrade du genom det fördärvade landskapet. Undercity är Hordes främsta fäste i norra Lordaeron och erbjuder skydd och mening under det gamla palatsets katakomber.",al={"hur hamnade jag här","hur kom jag till undercity","hur tar man sig till undercity"}},b63c4cf2={q="Vad förväntas jag göra i Undercity?",a="Du är här för att hjälpa Forsaken och samla Hordes styrkor mot farorna runt Lordaeron. I stadens koncentriska kvarter kan du rådfråga klassinstruktörer, skaffa förnödenheter och vända dig till Royal Apothecary Societys mörka forskare. Utöver att sköta ditt yrke ska du ta på dig uppdrag från Lady Sylvanas Windrunner och hennes löjtnanter. Forsaken utkämpar krig på flera fronter: de rensar bort resterna av den själlösa Scourge, driver tillbaka den fanatiska Scarlet Crusade och säkrar trygg mark där de odöda med fri vilja kan överleva.",al={"vad gör jag här","vad ska jag göra i undercity","varför är jag här"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Un'Goro Crater",s="Un'Goro Crater är en nedsänkt urskogsdjungel mellan Tanaris och Silithus torra ödemarker. Denna frodiga caldera domineras av kringströvande dinosaurier, levande elementaler och en central vulkan. Här finns uråldriga Titanreliker och kraftkristaller vars ursprung förblir ett stort mysterium.",h="Un'Goro Crater är en nedsänkt urskogsdjungel mellan Tanaris och Silithus torra ödemarker.",kw={"devilsaur","fire plume ridge","gudarnas land","lakkari","marshal's refuge","kraftkristaller","torwa pathfinder","ungoro","ungoro crater"},ang={["class:Druid"]="Druider från Cenarion Circle studerar Un'Goros isolerade ekosystem och skördar dess rika jord för att odla Morrowgrain. De försöker förstå den rena, otämjda livskraft som håller calderan vid liv.",["faction:Alliance"]="Alliansens naturkännare samlas kring Williden Marshal och J.D. Collie vid Marshal's Refuge. De tävlar om att tyda Titanpylonerna samtidigt som de skyddar forskare från Darnassus som samlar jordprover.",["faction:Horde"]="Hordens äventyrare anländer ofta via Tanaris för att pröva sin skicklighet mot legendariska devilsaurs och hjälpa Thunder Bluffs örtmästare att odla Morrowgrain från Un'Goros uråldriga jord.",["profession:Herbalism"]="Bäckenets rikliga fuktighet ger näring åt sällsynt växtlighet. Det är en av få platser i Kalimdor där Blindweed, Dreamfoil och Golden Sansam växer tillsammans med Firebloom på vulkanens sluttningar.",["profession:Mining"]="De branta kraterväggarna och klipporna vid Fire Plume Ridge är rika på Mithril Deposits och Rich Thorium Veins, vilket gör området till ett förstklassigt mål för den som söker malm av högsta kvalitet."},sec={{t="Gudarnas land",b="Un'Goro Crater ligger inklämd mellan vidsträckta öknar och trotsar södra Kalimdors geografi. Uråldriga Night Elf-arkiv om War of the Shifting Sands berättar att de insektsliknande Qiraji hejdades vid kraterns kanter och inte kunde tränga in i det som på deras språk kallades ”Gudarnas land”. Lärda tror att calderan tjänade som testområde eller forntida boplats för Titans när de formade Kalimdor. Stenpyloner reser sig längs bergsryggarna och surrar av energi, medan blå, röda, gröna och gula kristallformationer skjuter upp ur den uråldriga jorden."},{t="Ett vilt ekosystem",b="Un'Goro saknar städer, samhällen och ursprungliga humanoida folk. Här frodas livet i ett otämjt, uråldrigt tillstånd. Väldiga devilsaurs smyger över Terror Runs slätter, rovgiriga bloodpetals piskar till i The Marshlands och slemvarelser krälar över tjärgroparna i Lakkari. I kraterns mitt tornar Fire Plume Ridge upp sig, en aktiv vulkantopp full av fientliga eldelementaler som leds av varelsen Blazerunner. För upptäcktsresande och skinnare erbjuder bäckenet enastående naturtillgångar, däribland eftertraktade devilsaurhudar, om man överlever näringskedjan."},{t="Marshal's Refuge",b="Den civiliserade närvaron i kratern är nästan helt begränsad till Marshal's Refuge, ett upphöjt läger inbäddat i de norra klipporna. Under Williden Marshals ledning försökte en expedition med forskare, naturkännare och lyckosökare katalogisera bäckenets skatter, men de blev hårt ansatta av de monstruösa vilddjuren och drevs upp på högre mark. I dag fungerar lägret som en hårt prövad bas för oförvägna resenärer som studerar kraterns mystiska kraftkristaller, kartlägger vulkanisk aktivitet och håller vaksam uppsikt över silithidsvärmar som tränger igenom de södra bergsryggarna."}},faq={{q="Hur tar du dig in i Un'Goro Crater?",a="Resenärer kan ta sig in via naturliga sluttningar längs kraterväggarna. En finns i Tanaris sydvästra hörn nära Thistleshrub Valley, och en annan leder in från nordöstra Silithus. Vårdslösa äventyrare hoppar ibland nerför klipporna, men fallet är dödligt utan magisk hjälp. Marshal's Refuge i norr har flygförbindelser till Gadgetzan och Cenarion Hold.",al={"hur man tar sig in i ungoro","ingång till ungoro","hur man når ungoro crater"}},{q="Vad används de färgade kraftkristallerna till?",a="Röda, blå, gröna och gula Power Crystals ligger utspridda över djungelns mark. Med vägledning från gnomforskaren J.D. Collie vid Marshal's Refuge kan upptäcktsresande tyda instruktionerna för att använda kristallerna vid de norra, östra och västra pylonerna. När man kombinerar särskilda färger vid rätt pyloner utnyttjas vilande Titanenergier för att skapa skyddande eller läkande amuletter.",al={"ungoro-kristaller","röda blå gröna gula kristaller i ungoro","kraftpyloner"}},{q="Varför är Un'Goro frodigt trots att det omges av öknar?",a="Lärda tror att Un'Goros onaturliga växtkraft är konstgjord och härrör från Titans, som formade världen. Titaniska ledningar, varm geotermisk aktivitet från Fire Plume Ridge och uråldrig leyenergi ger näring åt ett isolerat ekosystem med extremt snabb tillväxt, som står emot det torra klimatet i grannområdena Tanaris och Silithus.",al={"varför ungoro är en djungel","ungoro och öknen","hur det växer växter i ungoro"}},{q="Varför kallade Qiraji platsen för ”Gudarnas land”?",a="Enligt tavlor som översatts från War of the Shifting Sands hejdades insektssvärmarna vid kraterns tröskel. Geologen Larksbane, som översatte berättelsen, kopplar namnet till teorierna om att Titans en gång bodde i kratern och undrar om Aman'Thul själv vakade över Gudarnas land.",al={"vad gudarnas land betyder","qiraji i ungoro","varför silithiderna inte kunde ta ungoro"}},{q="Vad används Un'Goro Soil till?",a="Högar av rik, kraftfull jord ligger utspridda över kraterbäckenet. När jorden samlas in kan den kombineras med Tharlendris-frön i en Evergreen Pouch för att odla Morrowgrain, en mystisk ört som forskare i Thunder Bluff, Darnassus och Cenarion Circle är mycket angelägna om.",al={"jordprov från ungoro","vad ungoro soil används till","morrowgrain och jord"}},{q="Finns det humanoida bosättningar eller grottor här?",a="I Un'Goro Crater finns en grotta, The Shaper's Terrace, för nivåerna cirka femtioåtta till sextio, men inga ursprungliga humanoida folk. Den enda permanenta bosättningen är Marshal's Refuge, en liten expeditionspost på den norra randen. Bortsett från enstaka eremitjägare eller vilsekomna upptäcktsresande är resten av calderan helt vildmark.",al={"grottor i ungoro","vem som bor i ungoro","humanoider i ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Wailing Caverns",s="Under Lushwater Oasis, i den torra The Barrens, ligger Wailing Caverns, ett labyrintiskt nätverk av underjordiska källor och sprickor som fått sitt namn efter den kusliga visslingen från instängd ånga. Det som började som ett ädelt druidiskt försök att återuppliva Kalimdors solblekta savann har förvandlats till en förvriden, giftig underjordisk värld. Grottorna myllrar nu av förvridet djurliv och fallna lärjungar som korrumperats av en djup, onaturlig mardröm.",h="Under Lushwater Oasis, i den torra The Barrens, ligger Wailing Caverns, ett labyrintiskt nätverk av...",kw={"deviate","druids of the fang","emerald nightmare","lady anacondra","lord cobrahn","lord pythas","lord serpentis","lushwater oasis","mutanus","naralex","verdan"},ang={["class:Druid"]="För druider av både Cenariontraditionen och taurenstammen är grottorna en tragisk varning om farorna i The Emerald Dream och en högtidlig plikt att rena sina fallna fränder, Druids of the Fang.",["race:NightElf"]="Naralex var en vördad gestalt bland nattälvdruider, och tragedin när han korrumperades av The Emerald Nightmare blev en smärtsam katastrof för hans folk på andra sidan havet.",["race:Tauren"]="De förvridna vattnen hotar de sårbara oaser som upprätthåller liv i The Barrens. Därför är det livsviktigt för stammarna i Mulgore och The Crossroads att källorna renas."},sec={{t="En ädel vision blir giftig",b="Nattälvdruiden Naralex upptäckte ursprungligen detta vidsträckta vattensystem och utformade en djärv plan: genom att öppna en kanal rakt in i The Emerald Dream skulle han leda ren, ursprunglig livsessens genom de underjordiska källorna och förvandla det uttorkade The Barrens till ett blomstrande, grönskande paradis. Djupt inne i grottorna föll Naralex i drömgemenskap, förankrad av sina lojala akolyter. Tragiskt nog berörde druidens sovande sinne The Emerald Nightmare i stället för att nå ren livskraft. Den ruttnande korruptionen tog genast över honom och förvandlade hans välmenade kanal till en ventil som pumpade gift och vansinne in i de underjordiska vattendragen."},{t="Druiderna av huggtanden",b="När mardrömmens mörka energi strålade från Naralex hjälplösa gestalt dukade hans elever under för vansinnet. De övergav Cenarion Circles fridfulla visdom och bildade den fanatiska gruppen Druids of the Fang. Ledarna tog reptilform: Lady Anacondra, Lord Cobrahn, Lord Pythas och Lord Serpentis. Nu bejakar de grottornas giftiga mutation i stället för att bekämpa den. De skyddar aktivt sin sovande mästare från all inblandning utifrån, eftersom de tror att denna förvridna tillväxt är naturens sanna utveckling."},{t="Mardrömmen blir kött",b="Att bryta Druids of the Fangs grepp räddar inte automatiskt Naralex. När hans återstående okorrumperade lärjungar inleder ritualen för att varsamt väcka honom ur transen vid Dreamer's Rock, stöter den sovande alvens vilda undermedvetna våldsamt bort sin djupaste skräck. Varelsen som bryter fram, en monstruös och förvriden murloc vid namn Mutanus the Devourer, är den fysiska manifestationen av Naralex värsta mardrömmar. Först när denna styggelse dödas kan förbindelsen till mardrömmen brytas. Då kan Naralex vakna, anta fågelform och flyga bort från de förgiftade grottorna."}},faq={{q="Varför heter platsen Wailing Caverns?",a="Grottan har fått sitt namn efter de sorgsna, tjutande rop som hörs genom gångarna. Ljuden uppstår naturligt när underjordiska ångventiler och kraftiga vindbyar pressas genom trånga sprickor i kalkstenen.",al={"varför heter det wailing caverns","namnets ursprung","varför ylar de"}},{q="Vad fick bestarna där inne att bli ”deviate”?",a="När Naralex hamnade under The Emerald Nightmares inflytande sipprade de förgiftade drömkrafterna direkt ut i de underjordiska källorna. När de naturliga rovödlorna, krokilisks och ormarna drack av och levde i det förorenade vattnet muterade de till onaturliga ”deviate”-varianter.",al={"deviate-korruption","varför muterar rovödlorna","deviate-bestarnas ursprung"}},{q="Vilka är Druids of the Fang?",a="De var en gång Naralex hängivna nattälvs- och taurenakolyter. Mardrömmen korrumperade dem tillsammans med honom, och deras sinnen bröts sönder. Deras druidiska konster förvriddes till dyrkan av ormar och gift, och de antog titlar som Cobrahn, Pythas och Anacondra.",al={"druiderna av huggtanden","lore om druiderna av huggtanden","vem är serpentis"}},{q="Varför är den sista bossen en jättelik murloc vid namn Mutanus?",a="Mutanus dyker upp under försöket att väcka Naralex. Varelsens natur och koppling till den sovande druiden avslöjas när ritualen fortskrider.",al={"varför är mutanus en murloc","vad är mutanus","lore om sista bossen"}},{q="Vad händer efter att Mutanus besegrats?",a="Lärjungens försök att väcka Naralex fortsätter efter mötet. Druidens öde avslöjas i slutet av ritualen.",al={"väcka naralex","naralex slut","vad händer med naralex"}},{q="Vem bor i grottan ovanför ingången?",a="Inne i grottans skalliknande ögonhåla sitter lojala medlemmar av Cenarion Circle, däribland Nalpak och Ebru. De söker modiga resenärer som kan samla in deviatehudar och rena bort korruptionen innan den helt uppslukar The Barrens.",al={"grottan ovanför ingången","npc:er i ormskallens ögonhåla","vilka är nalpak och ebru"}}},fx={["3386ab3f"]={q="Vad är Wailing Caverns?",a="Wailing Caverns är ett vidsträckt nätverk av underjordiska grottor under det torra Barrens, nära Lushwater Oasis. Naturliga källor under jord leder vatten flera kilometer genom marken och försörjer de sällsynta oaserna vid ytan i hela trakten. Grottorna upptäcktes av nattalven Naralex och skulle bli hjärtat i ett storslaget projekt för naturens återväxt. I stället blev de ett centrum för farlig korruption efter att en tragisk katastrof drabbade druiderna där inne.",al={"vad är wailing caverns","översikt över wailing caverns","om wailing caverns"}},e070a543={q="Vilka lever där nere?",a="Grottorna vimlar av onaturliga vilddjur och avfälliga druider. Naralex fördärvade anhängare, Druids of the Fang, har gjort tunnlarna till sitt revir tillsammans med muterade ormar, slemvarelser, rovfåglar och krokolisker. Utanför instansens ingång lurar vilddjur, slemvarelser och till och med utstötta i de fuktiga gångarna. De fördärvade druiderna vaktar de inre kamrarna och skyddar sin sovande mästare.",al={"vilka finns i wailing caverns","varelser i wailing caverns","invånare i wailing caverns"}},["49d47201"]={q="Varför skickade Horde mig hit?",a="De lokala bestarnas märkliga mutationer och den vidriga energi som bubblar upp ur Lushwater Oasis hotar hela Barrens. Horde och Cenarion-druiderna i Thunder Bluff kan inte tolerera en okontrollerad mörk kraft som förgiftar landet och vattendragen alldeles intill The Crossroads. Du skickades hit för att undersöka saken, göra slut på Fangs avfälliga ledare och hjälpa till att hejda den växande faran.",al={"varför är jag i wailing caverns","hordes uppdrag i wailing caverns","varför skickas jag till wailing caverns"}},d445bb78={q="Är det här en del av ett större problem i Barrens?",a="Ja. De underjordiska kanalerna under grottorna förser oaserna vid ytan i hela Barrens med vatten. Marans smitta som fördärvar vattnet i grottorna har börjat sprida sig ut i landskapet. Den får vilda varelser som rovfåglar och krokolisker att mutera och förvandlar Lushwater Oasis till en grogrund för märkliga avvikande livsformer.",al={"oaseproblemet i barrens","avvikande korruption i barrens","påverkar wailing caverns barrens"}},["038fd1cf"]={q="Sprider sig de avvikande varelserna utanför grottorna?",a="De gör redan det. De underjordiska källorna rinner direkt ut i oaser vid ytan, som Lushwater, och för med sig onaturlig växtlighet och muterade varelser till den öppna savannen. Märkliga varelser som Deviate Fish kan fångas i vattnen utanför, och aggressiva muterade rovdjur angriper allt oftare resenärer mellan oaserna och The Crossroads.",al={"sprider sig avvikarna","avvikande bestar i barrens","deviate fish utanför"}},["8502642f"]={q="Vem styr här nere?",a="Medan Naralex ligger fångad i sin fördärvade sömn djupt inne i grottorna, styr Ormens Druider till vardags över hålorna. De leds av Lord Serpentis, en gång Naralex främsta elev, som samlade sina förvridna bröder för att forma om landet till sitt eget förvridna paradis tillsammans med andra huggtandsfurstar som Cobrahn, Pythas och Lady Anacondra.",al={"vem leder wailing caverns","ledare för wailing caverns","boss i wailing caverns"}},["32be29c8"]={q="Vad är Emerald Dream, och hur hänger den ihop med den här grottan?",a="Emerald Dream är en vidsträckt andevärld som föreställer Azeroth orört och vilt. Den förvaltas av den gröna drakflocken och är tillgänglig för druider. Naralex trodde att han kunde leda drömmens rena, återställande krafter till Wailing Caverns underjordiska vattenådror för att återställa frodig växtlighet i The Barrens. Men när han tog kraften i anspråk snärjdes han av Emerald Nightmare, som projicerade en förvriden version av naturen in i de fysiska grottorna.",al={"koppling till emerald dream","wailing caverns och emerald dream","naralex och emerald dream"}},["38e519c2"]={q="Varför är alla så oroliga för den här platsen?",a="Källorna under grottorna förser de viktigaste oaserna som upprätthåller liv i hela det torra The Barrens. Om Emerald Nightmares smitta fortsätter att sippra ut i vattendragen utan att hejdas, kan de förvridna mutationerna och vansinnet som fördärvar grottans växt- och djurliv sprida sig över hela regionen och förvandla landet till en levande mardröm.",al={"varför oroa sig för wailing caverns","hotet från wailing caverns mot the barrens","hur farligt är wailing caverns"}},["81917ac6"]={q="Hur hamnade jag i Wailing Caverns?",a="Du reste söderut från The Crossroads till Lushwater Oasis efter rapporter om märkliga bestar och förgiftat vatten som läckte ut i The Barrens. Bakom den frodiga växtligheten och Kolkar-centaurernas läger ligger en väldig, skallformad grotta uthuggen ur berget. Lockad av rop på hjälp från Thunder Bluff, av Ratchets gobliner som sökte märkliga essenser eller av lärjungar som slagit läger i skallens ögonhåla ovanför, tog du dig ner förbi slingrande sprickor och underjordiska gejsrar som väste, till djupens stönande mörker.",al={"hur kom jag hit","hur tar jag mig till wailing caverns","var kom jag ifrån när jag kom hit"}},["28a012f3"]={q="Vad förväntas jag göra i Wailing Caverns?",a="Du är här för att rena den underjordiska källan från den korruption som har gripit tag i den. Nattelven Naralex föll i en mardrömslik sömn när han försökte återuppliva The Barrens, vilket förvrängde varelserna där inne och drev hans lärjungar till att bli de giftiga Ormens Druider. Du måste jaga rätt på de fyra huggtandsfurstarna: Lady Anacondra, Lord Cobrahn, Lord Pythas och Lord Serpentis, för att bryta deras grepp. Hjälp sedan den lärjunge som är kvar att väcka Naralex innan hans feberdröm slukar oasen helt.",al={"vad är mitt mål här","varför är jag i wailing caverns","vad gör jag här nere"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Warsong Gulch",s="Warsong Gulch är en skogsklädd dal mellan Ashenvale och The Barrens, där Horde och Alliance utkämpar ett ständigt slag. Orcer från Warsong-klanen hugger ner Ashenvales träd åt Horde, och Night Elf-folket vid Silverwing Hold kämpar för att driva bort dem från den heliga skogen. Krigare av alla raser kommer för att bidra med svärd eller magi, medan båda sidor plundrar den andras fäste för att föra bort dess fana.",h="Warsong Gulch är en skogsklädd dal mellan Ashenvale och The Barrens, där Horde och Alliance utkämpar ett...",kw={"warsong gulch","slagfält","warsong outriders","silverwing sentinels","silverwing hold","warsong-sågverket","flagga","virke","ashenvale","grom hellscream"},ang={["faction:Alliance"]="Alliansens soldater slåss här för sina Night Elf-allierade, vars heliga skog faller träd för träd under Warsong-klanens yxor.",["faction:Horde"]="Varje stock som lämnar Warsong-sågverket blir en Horde-mur någonstans i Kalimdor. Att hålla dalen säkerställer att Horde kan fortsätta bygga.",["race:NightElf"]="Kaldorei har vandrat i dessa skogar i tiotusen år. Varje orch som drivs ut ur dalen innebär att en bit av Ashenvale återtas.",["race:Orc"]="Warsong-klanen är Grom Hellscreams egen, och i dalen gör hans krigare fortfarande skäl för sitt namn, med yxan i hand mot väktarna."},sec={{t="Virke och blod",b="Horde byggde sitt nya hem i Kalimdor av trä, och mycket av det kommer från Ashenvale. Warsong-klanen, Grom Hellscreams krigare, har huggit sig in i skogen sedan Horde först landsteg, och deras sågverk vid dalens ände förser Hordes läger och murar med virke. För Night Elf-folket är varje fällt träd ett sår i en skog de har vaktat i tiotusen år, och de har inte glömt att Groms krigare en gång dödade Cenarius i dessa skogar."},{t="Utposter och väktare",b="Hordes krigare här är Warsong Outriders, som får förnödenheter från Mor'shan Base Camp vid The Barrens norra gräns, där Kelm Hargunth ser till att de har vapen och mat. Mot dem står Silverwing Sentinels från Silverwing Hold, Night Elf-krigare som svurit att driva varje inkräktare ut ur Ashenvale. Illiyana Moonblaze förser dem med förnödenheter från Silverwing Grove. Allierade från båda sidor strömmar till dalen: dvärgar och människor ställer sig vid väktarnas sida, tauren, troll och Forsaken vid utposternas."},{t="Kampen om fanorna",b="Båda sidor har ett fäste vid varsin ände av dalen: Warsong-sågverket för Horde och Silverwing Hold för Night Elf-folket. Båda förvarar sin fana där. Striden går ut på att plundra: krigare bryter sig in i fiendens fäste, tar dess flagga och rusar tillbaka till sitt eget medan försvararna jagar dem. Varje flagga som förs hem blir ett slag mot fiendens stolthet, och sidan som erövrar flest vinner dagen."}},faq={{q="Vad är Warsong Gulch?",a="Warsong Gulch är en slagmark i en skogsklädd dal mellan Ashenvale och The Barrens. Hordes Warsong Outriders och Night Elf-folkets Silverwing Sentinels slåss där om Hordes skogsavverkning i Ashenvale, och båda sidor försöker erövra den andras flagga.",al={"vad är warsong gulch","warsong gulch slagfält","wsg"}},{q="Varför slåss Horde i Warsong Gulch?",a="Horde behöver virke från Ashenvale för att bygga och försvara sitt hem i Kalimdor. Warsong-klanens sågverk i dalen är en av Hordes viktigaste källor, och Outriders försvarar det så att Hordes läger och murar kan fortsätta växa.",al={"hordes intressen i warsong gulch","varför avverkar orcerna ashenvale","warsong outriders motiv"}},{q="Varför slåss Night Elf-folket i Warsong Gulch?",a="För Night Elf-folket är Ashenvale en helig skog som de har vaktat i tiotusen år, och Warsong-klanen dödade en gång halvguden Cenarius där. Silverwing Sentinels kämpar för att stoppa skogsavverkningen och driva ut orcerna ur sina skogar, och resten av Alliance står vid deras sida.",al={"alliansens intressen i warsong gulch","varför slåss väktarna","silverwing sentinels motiv"}},{q="Vilka är Warsong Outriders?",a="Warsong Outriders är Hordes krigare i Warsong Gulch, rekryterade från Warsong-klanen som en gång leddes av Grom Hellscream. De får förnödenheter från Mor'shan Base Camp i norra The Barrens, där Kelm Hargunth utrustar dem som slåss för dem.",al={"warsong outriders","warsong-klanens krigare","kelm hargunth"}},{q="Vilka är Silverwing Sentinels?",a="Silverwing Sentinels är Night Elf-krigare från Silverwing Hold, som har svurit att driva ut Horde ur Ashenvale. Illiyana Moonblaze vid Silverwing Grove förser Alliansens hjältar med utrustning när de slåss vid deras sida i dalen.",al={"silverwing sentinels","silverwing hold","illiyana moonblaze"}},{q="Hur vinner man slaget i Warsong Gulch?",a="Båda sidor förvarar sin flagga i sitt eget fäste. Krigare plundrar fiendens bas, tar dess flagga och för den tillbaka till sitt eget fäste medan de försvarar sin fana. Sidan som för hem flest flaggor vinner.",al={"målen i warsong gulch","erövra flaggan i warsong gulch","hur man vinner warsong gulch"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Western Plaguelands",s="Western Plaguelands var en gång norra Lordaerons bördiga kornbod. Nu kvävs området av giftig dimma och horder av odöda. Kel'Thuzads kittlar ödelade gårdarna och städerna, men jorden klamrar sig envist fast vid livet. Argent Dawn, Alliance, Forsaken och Scarlet Crusade för desperata fälttåg över de fördärvade fälten.",h="Western Plaguelands var en gång norra Lordaerons bördiga kornbod.",kw={"andorhal","the bulwark","caer darrow","pestkittlar","chillwind camp","hearthglen","mardenholde keep","scholomance","uther's tomb","western plaguelands"},ang={["class:Paladin"]="Lordaerons vanhelgade fält är en dyster prövning för heliga krigare. Här kan du vallfärda till Uther's Tomb och föra ett rättfärdigt krig mot fasorna i Scholomance och Hearthglens fördärvade fanatiker.",["faction:Alliance"]="Chillwind Camp är Alliance främsta garnison vid fronten. Där leder Commander Ashlam Valorfist fälttåg för att slå ut pestkittlarna och hämnas Lordaerons fallna städer.",["faction:Horde"]="The Bulwark markerar gränsen för Forsakens välde. Härifrån rycker Horde österut för att oskadliggöra befälhavare från Scourge och utmana Scarlet Crusades fanatiker längs deras utsatta flank.",["profession:Herbalism"]="Den kvardröjande smittan gör området till en av få platser där sällsynta och farliga växter som Plaguebloom och Arthas' Tears kan slå rot bland fördärvade tallskogar."},sec={{t="Lordaerons kornbod",b="Före det tredje kriget var landet en grönskande korridor av gårdar som sträckte sig österut från Tirisfal Glades mot Darrowmere Lake. Hearthglen skötte den norra förvaltningen från Mardenholde Keep, medan den vidsträckta staden Andorhal organiserade lagringen och exporten av spannmål i hela kungariket. Den viktiga jordbruksrollen gjorde området till Kel'Thuzads främsta mål. Genom att föra in odödhetens pest direkt i spannmålsleveranserna i Andorhal förvandlade The Cult of the Damned Lordaerons föda till dess undergång."},{t="Ett land under belägring",b="För att förgifta jorden för alltid reste Scourge fyra enorma pestkittlar på de största jordbruken: Felstone Field, Dalson's Tears, The Writhing Haunt och Gahrron's Withering. I dag sköter monstruösa kittelherrar dessa giftiga kar och pumpar ut giftig dimma i luften. Träden runt omkring vrider sig av svullna, tumörliknande utväxter, och fördärvat djurliv härjar i snåren. Under Caer Darrow på Darrowmere Lake utbildar Darkmaster Gandling nekromantiker i Scholomance, vilket förvärrar hotet från de odöda."},{t="Splittrade fraktioner",b="Trots att Scourge finns överallt håller flera fraktioner fast vid utsatta fästen. Scarlet Crusade kontrollerar fästningen Hearthglen i norr och renar allt de anser vara besmittat med fanatisk iver. I söder utgår Alliance-styrkor från Chillwind Camp, medan Forsaken försvarar sina gränser vid The Bulwark. Den neutrala Argent Dawn samordnar kampen mot de odöda kittlarna och vägleder den. Orden hjälper hjältar från båda fraktionerna och vaktar Uther's Tomb, den sista verkligt helgade marken i området."}},faq={{q="Varför drabbade pesten området så hårt?",a="Andorhal var norra Lordaerons knutpunkt för spannmålstransporter. Kel'Thuzad riktade avsiktligt in sig på områdets försörjning, infekterade spannmålssilor och ställde upp enorma pestkittlar på fyra stora jordbruk för att snabbt sprida odödhet genom matleveranser i hela kungariket.",al={"varför är western plaguelands pesthärjat","vad hände med andorhal","varför finns kittlar här"}},{q="Vem kontrollerar Hearthglen i norr?",a="Hearthglen och dess fästning, Mardenholde Keep, styrs av Scarlet Crusade. Platsen var ursprungligen ett regionalt förvaltningscentrum för Lordaeron, men fanatikerna avrättar nu alla utomstående som närmar sig deras gränser. De betraktar alla som inte tillhör korståget med misstänksamhet.",al={"hearthglens fraktion","vilka bor i mardenholde keep","är hearthglen vänligt"}},{q="Var hittar Alliance- och Horde-spelare säkra utposter?",a="Alliance håller till vid Chillwind Camp nära den södra gränsen mot Alterac Mountains. Där finns en flygmästare och allierade från Argent Dawn. Horde utgår från The Bulwark vid den västra gränsen, där vägen in från Tirisfal Glades går.",al={"var finns flygrutterna","hordes läger i wpl","alliances läger i wpl"}},{q="Vad har pestkittlarna på fälten för syfte?",a="The Cult of the Damned reste dessa kittlar vid Felstone Field, Dalson's Tears, The Writhing Haunt och Gahrron's Withering. De pumpar ständigt ut pestångor i luften och jorden. Agenter från Argent Dawn rekryterar äventyrare för att döda kittelherrarna och motverka de giftiga brygderna.",al={"vad är pestkittlarna","kittlarnas syfte","felstones pestkittel"}},{q="Vad är Scholomance och var ligger det?",a="Scholomance är en underjordisk nekromantiskola som drivs av Scourge och The Cult of the Damned. Den ligger gömd under ruinerna av Caer Darrow, en fästningsö i den sydöstra delen av Darrowmere Lake.",al={"scholomances plats","var ligger scholomance","caer darrow-instans"}},{q="Finns det någon del av Western Plaguelands som är ofördärvad?",a="Uther's Tomb ligger på Sorrow Hill nära områdets södra kant och är fortfarande helt helig och orörd av fördärvet. Den står som ett helgat minnesmärke över den fallne högste generalen Uther the Lightbringer och den förlorade Order of the Silver Hand.",al={"helig mark i wpl","är uthers grav orörd","är uther's tomb säker"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Westfall",s="Westfalls gårdar ligger oskyddade, och Defias Brotherhood kontrollerar stora delar av landsbygden. Området var en gång Stormwinds kornbod, men kämpar nu utan kronans stöd eller militära garnisoner.",h="Westfalls gårdar ligger oskyddade, och Defias Brotherhood kontrollerar stora delar av landsbygden.",kw={"the deadmines","defias","skördegolem","milis","moonbrook","saldean","sentinel hill","stoutmantle","vancleef","westfall"},ang={["class:Rogue"]="Som skurk finner du ett skuggkrig i hela Westfall, där SI:7:s spioner möter Defias Brotherhoods gatukloka spejare, tjuvar och lönnmördare.",["faction:Alliance"]="Som alliansresenär kan du se hur People's Militia håller stånd i Sentinel Hill. Utan den skulle Defias Brotherhood kontrollera de södra vägarna till Elwynn Forest.",["profession:Cooking"]="Som kock kan du lära dig hur de hårt prövade nybyggarna på Saldean's Farm klarar sig med tuffa lokala bestar och lär resenärer att tillaga Westfall Stew.",["race:Human"]="Som människa visar Westfall Stormwinds politiska förfall. Bönderna som svälter i smutsen övergavs av adeln de slet för att försörja."},sec={{t="Ett övergivet land",b="Westfall försörjde en gång kungariket Stormwind med sina betesmarker och vetefält. Efter det andra kriget sinade kungarikets finanser, och dess ledare försummade området. Stormwind skickade resurser någon annanstans och drog in sina garnisoner, så att marken låg obrukad. Nu gör karga betesmarker, hårda kustvindar, skenande skördegolemer och Riverpaw-gnoller det svårt för de få nybyggare som är kvar att överleva."},{t="Brotherhood växer sig starkt",b="Defias Brotherhoods ankomst påskyndade Westfalls sammanbrott. Banditerna bär röda masker och följer en ledare vars namn ingen på landsbygden känner till. De gjorde Westfall till sitt fäste, brände böndernas fält, saltade jorden och tog över övergivna gruvor. Från Moonbrook, en spökstad, styr Brotherhood större delen av landsbygden i allt utom namnet."},{t="Folkets milis",b="House of Nobles har ignorerat Westfalls nöd, så lokalbefolkningen har tagit sitt försvar i egna händer. I Sentinel Hill bildade Gryan Stoutmantle People's Militia, en frivillig styrka som håller stånd mot gnoller och banditer. Stormwind skickar inga reguljära soldater eller förnödenheter. Milisen är beroende av kringvandrande äventyrare för att slå tillbaka Defias och skydda de gårdar som finns kvar."},{t="Stenhuggare i röda masker",b="Edwin VanCleef leder Brotherhood. Han var gillesmästaren som återuppbyggde Stormwind City, men House of Nobles nekade hans stenhuggare deras lön, och upplopp drev bort dem. De tog på sig den röda masken i Westfall. Banditerna som bränner dess fält är samma händer som reste huvudstadens murar."},{t="Sammansvärjningen i Deadmines",b="Under Moonbrook har Edwin VanCleef samlat stråtrövare, gobliner och avfällingar i Deadmines övergivna guldgruvor. Brotherhood bygger där en väldig bepansrad best, avsedd att segla längs kusten och bombardera Stormwind City."}},faq={{q="Varför står så många gårdar övergivna i Westfall?",a="Stormwind drog in sina garnisoner när underhållet blev för dyrt och lämnade Westfall oskyddat. Defias Brotherhood tog sedan över stora delar av landsbygden, drev bort nybyggare, brände åkrar och programmerade om mekaniska skördevakter till dödliga väktare.",al={"övergivna gårdar","varför är westfall öde","varför ligger marken obrukad"}},{q="Varför skickar Stormwind inga trupper för att hjälpa Westfall?",a="Kungarikets skattkammare är ansträngd, och House of Nobles prioriterar hot i andra länder högre. Intriger vid hovet har också i det tysta berövat Westfall uppmärksamhet och förnödenheter, så invånarna får försvara sig själva.",al={"varför finns ingen stormwind-armé","var är vakterna","stormwinds hjälp"}},{q="Vad är People's Militia?",a="Gryan Stoutmantle organiserade People's Militia i Sentinel Hill för att försvara Westfall. Utan soldater från kronan anslöt sig bönder och nybyggare för att bekämpa Defias Brotherhood och Riverpaw-gnollerna.",al={"folkets milis","sentinel hills milis","gryan stoutmantles armé"}},{q="Vem leder Defias Brotherhood i Westfall?",a="Edwin VanCleef, tidigare gillesmästare i Stonemasons Guild, leder Defias Brotherhood. Han övervakade återuppbyggnaden av Stormwind City och ledde sedan sina arbetare till Westfall och beväpnade dem efter att en bitter lönetvist slutat i upplopp.",al={"defias ledare","vem leder defias","vancleef"}},{q="Vad döljer sig i Moonbrook?",a="Under en oansenlig lada i Moonbrook finns ingången till Deadmines. Defias Brotherhood gjorde den övergivna guldgruvan till en underjordisk fästning och ett skeppsvarv för sitt krig mot Stormwind.",al={"moonbrooks hemlighet","vad finns i deadmines","moonbrooks gruva"}},{q="Varför angriper de mekaniska fågelskrämmorna människor?",a="Goblinmekaniker med band till Defias tillfångatog de mekaniska skördevakterna, som ursprungligen byggdes för att sköta grödorna och skrämma bort skadedjur. De byggde om dem så att de patrullerar fälten och dödar inkräktare.",al={"skördegolemer anfaller","skördevakter","onda fågelskrämmor"}}},fx={cd1e134e={q="Vad är Westfall?",a="Westfall är det vindpinade västra territoriet i Stormwinds kungarike, väster om Elwynn Forest och söderut till havet. En gång var det kungarikets bördiga kornbod, vars böljande kullar och vida betesmarker försörjde Stormwind i generationer. I dag har landet försummats av kronan och härjats av konflikter, och förfallit till trädlösa dammslätter, förstörda gårdar och laglöst territorium.",al={"vad är det här för zon","berätta om westfall","westfalls historia"}},["44cadea7"]={q="Varför är det så tomt här ute?",a="En förvärrande blandning av torka, försummelse och banditvälde tömde landsbygden på folk. Efter det andra kriget riktade Stormwind sina soldater åt annat håll och lämnade de lokala gårdarna försvarslösa. När Defias Brotherhood gjorde uppror drev de bort bönder, brände odlingar och saltade åkrarna. Utan kungliga garnisoner som kunde skydda dem flydde eller svalt de flesta invånarna.",al={"varför är westfall öde","varför är det så tomt","varför bor det ingen här"}},["1a97e791"]={q="Var Westfall alltid så fattigt?",a="Inte alls. I generationer var Westfall Stormwinds stolta jordbrukshjärta, känt för sina gyllene vetefält, bördiga jordar och rika guldgruvor som Jangolode och The Deadmines. Maten därifrån försörjde huvudstaden och gruvorna fyllde de kungliga skattkamrarna, innan krig och oroligheter i riket lämnade landet öde.",al={"var westfall alltid fattigt","var westfall rikt förr","westfalls förflutna"}},["1d4a9481"]={q="Vilka är Defias Brotherhood?",a="Defias Brotherhood är en stor kriminell organisation bestående av avhoppade stenhuggare, tjuvar, rövare och utstötta. Under ledning av Edwin VanCleef tog de över Westfalls övergivna jordbruk och gruvor för att föra ett bittert skuggkrig mot Stormwinds kungarike. De vill utkräva hämnd för obetalda skulder och svek som de anser sig ha utsatts för.",al={"vilka är defias","vad är defias brotherhood","vilka är de här banditerna"}},b6953315={q="Varför bär Defias röda bandanas?",a="Röda bandanas är Defias Brotherhoods kännetecken, och materialet visar en medlems rang. Röda sidenbandanas bärs av medlemmar med högre rang. Scout Riell ber äventyrare samla in dem som bevis på att medlemmarna har dödats.",al={"varför röda bandanas","defias röda masker","vad betyder de röda maskerna"}},["908b4fe1"]={q="Vad vill Defias ha i Westfall?",a="De ser Westfall som sitt självständiga fäste och sin uppmarschplats. Genom att kontrollera guldgruvorna, lägga beslag på matförråd och driva bort bönder som är lojala mot kronan kan de i hemlighet bygga upp sina styrkor och sin krigsmateriel utom synhåll för Stormwind, samtidigt som de smider planer på att störta kungariket.",al={"vad vill defias ha","defias mål i westfall","varför är defias i westfall"}},d384bc2d={q="Varför skickades jag till Westfall?",a="Du skickades hit eftersom Stormwinds reguljära militär vägrar eller misslyckas med att sända trupper till Westfall, så territoriet riskerar att helt falla i banditernas händer. Myndigheterna i Elwynn skickar skickliga äventyrare västerut för att hjälpa de kämpande lokalborna, som är i desperat behov av hjälp.",al={"varför är jag i westfall","vem skickade mig till westfall","varför skickades jag hit"}},d59f010f={q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle är en paladin av Silver Hand och född i Westfall. När han återvände hem efter striderna i Lordaeron under det tredje kriget fann han sitt hemland översvämmat av banditer och övergivet av Stormwinds militär. Som svar samlade han lokala försvarare och grundade Folkets milis vid Sentinel Hill.",al={"vem är stoutmantle","gryan stoutmantle","vem leder sentinel hill"}},af1c3ddb={q="Är Gryan Stoutmantle verkligen den som styr Westfall?",a="I praktiken, ja. Pojkkungen i Stormwind har det lagliga anspråket på Westfall, men kronan utövar knappt någon faktisk makt här. Stoutmantle och hans frivilliga milis vid Sentinel Hill utgör det enda fungerande försvaret och den enda lagupprätthållande styrkan som finns kvar i riket.",al={"vem styr westfall","är stoutmantle ledaren","vem bestämmer"}},c01912f7={q="Vad hände med Stonemasons Guild?",a="Under guildmästaren Edwin VanCleef ägnade sig Stonemasons Guild i åratal åt att återuppbygga Stormwind City efter det första kriget. När arbetet var klart vägrade Adelsrådet att betala den överenskomna summan. Efter att fredliga vädjanden misslyckats upplöstes gillet med våld, vilket utlöste rasande upplopp som drev stenhuggarna i exil.",al={"vad hände med stonemasons","stonemasons guilds historia","vilka var stenhuggarna"}},ec2fd06e={q="Vägrade Stormwind verkligen att betala stenhuggarna?",a="Ja. Adelsrådet hade dragit på sig enorma skulder genom att utöka militära expeditioner på andra håll, vilket nästan gjorde kungariket bankrutt. Påverkade av hovintriger och aristokratisk arrogans erbjöd adelsmännen bara småsmulor för ett enormt arbete och vägrade helt att hålla sig till de fullständiga avtalen.",al={"lurade stormwind stenhuggarna","varför betalade inte adelsmännen","tvisten om stenhuggarnas betalning"}},cf60f690={q="Varför finns det så många gnoller i Westfall?",a="Gnollerna i Riverpaw-flocken har tagit sig över gränsen för att utnyttja frånvaron av Stormwinds soldater. Än värre är att Defias Brotherhood aktivt anställde dem som legosoldater och placerade dem bland kullarna och slätterna, där de ligger i bakhåll för resande och trakasserar de gårdar som finns kvar.",al={"varför är gnollerna här","riverpaw-gnoller i westfall","danuvin-gnoller"}},e40fa3bd={q="Vad är Moonbrook?",a="Moonbrook var en gång den främsta marknads- och gruvstaden i södra Westfall. Staden ligger ovanför den uråldriga ingången till The Deadmines och togs helt över och tömdes av Defias Brotherhood. De använder nu de tomma byggnaderna som vaktpost runt sitt underjordiska fäste.",al={"vad är moonbrook","moonbrooks historia","berätta om moonbrook"}},["46f1c864"]={q="Vart leder utredningen av Defias?",a="Din utredning avslöjar Brotherhoods hemliga hjärta under Moonbrook, i The Deadmines. Där, djupt inne i de underjordiska grottorna, övervakar Edwin VanCleef bygget av en väldig bepansrad best avsedd att bombardera Stormwind från havet. Det leder till en direkt attack mot guildmästaren själv.",al={"vart leder defias uppdrag","hur slutar defias historia","slutet på the deadmines"}},["27471424"]={q="Hur hamnade jag i Westfall?",a="Du korsade troligen flodbron från Elwynn Forest och följde vägen västerut, dit du skickats av myndigheterna eller vänner till Sentinel Hill. Stormwind har fullt upp och kan inte avvara kungliga trupper, så ryktet har spridit sig i grannländerna att Gryan Stoutmantle och de lokala bönderna desperat behöver hjälp av dugligt folk. Oavsett om du kom till fots efter en vädjan om hjälp eller bara följde kungsvägen i jakt på arbete, har du tagit dig in i ett rike som kungarikets soldater nästan helt har övergett.",al={"hur kom jag hit","hur kom jag till westfall","hur hamnade jag här"}},["6324593c"]={q="Vad förväntas jag göra i Westfall?",a="Ditt främsta uppdrag är att hjälpa People's Militia vid Sentinel Hill att slå tillbaka de otaliga hot som plågar provinsen. Gryan Stoutmantle behöver frivilliga som gallrar bland de aggressiva vilddjuren, tystar de förrymda skördeväktarna som stryker omkring på obrukade fält och driver tillbaka Riverpaw-gnollerna. Framför allt ska du spåra upp den svårfångade Defias Brotherhood, ta reda på var de gömmer sig och bryta deras järngrepp om det som återstår av Westfalls kämpande gårdar.",al={"vad ska jag göra här","vad gör jag i westfall","varför är jag här"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Wetlands",s="The Wetlands är ett vidsträckt, dimhöljt träsk mellan Khaz Modans berg och Baradin Bays stränder. Området har härjats av dvärgakrig och invasioner från orcher och fungerar som en karg buffert mellan Ironforge och Lordaerons nordliga länder. Den befästa hamnen Menethil Harbor är Alliansens främsta livlina i en blöt vildmark som översvämmas av Dragonmaw-orcher, murlocer och gnoller.",h="The Wetlands är ett vidsträckt, dimhöljt träsk mellan Khaz Modans berg och Baradin Bays stränder.",kw={"baradin bay","dragonmaw","dun algaz","dun modr","grim batol","menethil","menethil harbor","thandol span","wetlands"},ang={["faction:Alliance"]="Menethil Harbor är Alliansens främsta djupvattenhamn för färder över Great Sea och förbinder de östra kungadömena med expeditionsutposter i Kalimdor.",["profession:Mining"]="Kullarna och grottorna i Thelgen Rock rymmer rika mineralådror, däribland sällsynta fyndigheter av Incendicite Ore som dvärggruvare och ingenjörer eftertraktar.",["race:Dwarf"]="För dvärgar är Wetlands en bitterljuv plats, präglad av förlusten av Dun Modr, Grim Batols uråldriga tragedi och det ständiga arbetet med att försvara kung Magni:s handelsväg norrut."},sec={{t="Ett land av vatten och ruiner",b="Under Stonewrought Dams höga stup breder Wetlands ut sig som en kall, vattensjuk trakt, höljd i ständig dimma och grå himmel. Här fanns en gång livliga dvärgbosättningar, men nu ligger sjunkna stenruiner, blöta träsk och förrädiska kärr utspridda över området. Äventyrare som tar sig in måste färdas genom smala pass, antingen norrut genom Dun Algaz barrikaderade ravin från Loch Modan eller över Thandol Spans höga valv från Arathi Highlands."},{t="Grim Batols ärr",b="Träskets östra delar domineras av Grim Batols hotfulla närvaro, det tidigare fästet för Wildhammer. Efter att platsen skändats under hammarnas tre krig blev den Dragonmaw-klanens befästa tillflykt under andra kriget. När den röda drakflykten bröt sig fri ur orchernas fångenskap krossade deras flammande hämnd orchernas styrkor och ödelade de omgivande sluttningarna. I dag vaktar röda drakspawn och wyrmkin Dragonmaw Gates mot alla inkräktare, medan förvildade rester av Dragonmaw-klanen bor i utspridda läger i kullarna och fortsätter att trakassera resande genom träsket."},{t="Västkustens hamn",b="Menethil Harbor ligger vid Baradin Bays kant och är hjärtat i Alliansens handel och logistik i Khaz Modan. Hamnen har fått sitt namn till kung Terenas Menethil II:s ära och förbinder Eastern Kingdoms med avlägsna Kalimdor genom regelbundna transportfartyg till Theramore Isle och, via Southshore, till Auberdine. Trots sin strategiska militära betydelse och gedigna dvärgarkitektur hotas hamnen ständigt av kustnära murlocer, träskvarelser och plundrare som angriper fartyg i de klippiga farlederna."},{t="Belägrade gränstrakter",b="Wetlands är en aktiv krigszon på flera fronter. Längst i norr har Dark Iron-dvärgar under häxmästaren Balgaras the Foul saboterat Thandol Span med bomber och tagit över staden Dun Modr, vilket skurit av landvägen för förnödenheter. Samtidigt härjar Mosshide-gnoller i de centrala kärrmarkerna och hotar till och med uråldriga beskyddare som Rethiel the Greenwarden. Mellan kringströvande orchkrigare, Dark Iron-infiltratörer och förbannade skeppsvrak längs kusten kräver det ständig vaksamhet att hålla träsket."}},faq={{q="Hur tar jag mig till Wetlands till fots?",a="Äventyrare från Alliansen reser vanligtvis norrut från Loch Modan genom bergspasset Dun Algaz. Hordens resande från norr kan ta sig över Thandol Span från Arathi Highlands. Var försiktig, eftersom båda vägarna är omstridda av fientliga styrkor som Dragonmaw-orcher och Dark Iron-dvärgar.",al={"hur man tar sig till wetlands","vägen till wetlands","ta sig till wetlands"}},{q="Vart går båtarna från Menethil Harbor?",a="Däcken i Menethil Harbor har två stora färjerutter till Kalimdor. Det ena fartyget anlöper Southshore i Hillsbrad Foothills och seglar sedan över Great Sea till Auberdine vid Darkshores kust. Det andra seglar söderut till Theramore Isle i Dustwallow Marsh.",al={"menethils båtar","fartyg från menethil harbor","vart går båten i wetlands"}},{q="Vad är Grim Batol och varför vaktas det?",a="Grim Batol är en uråldrig dvärgfästning som övergavs efter hammarnas tre krig och senare ockuperades av Dragonmaw-klanen. Efter andra kriget drev den befriade röda drakflykten bort orcherna och förseglade berget. Mäktiga röda drakspawn och wyrmkin patrullerar Dragonmaw Gates för att hindra någon från att gå in i de förbannade salarna.",al={"varför finns det drakar vid grim batol","röda drakar i grim batol","dragonmaw gates"}},{q="Vad hände med Dun Modr?",a="Dun Modr var ett nordligt dvärgafäste som vaktade Thandol Span. Staden anfölls nyligen och intogs av Dark Iron-dvärgar ledda av Balgaras the Foul. De överlevande, ledda av Rhag Garmason, håller ett belägrat läger i närheten medan de kämpar för att återta staden.",al={"vem förstörde dun modr","dun modrs ruiner","dark iron i dun modr"}},{q="Vem är Rethiel the Greenwarden?",a="Rethiel är ett uråldrigt kärrvidunder som håller till i Wetlands Green Belt. Han söker hjälp från resande för att hejda de aggressiva Mosshide-gnollerna och göra slut på sjuka Fen Creepers så att kärrmarkerna kan återhämta sig.",al={"the green belt","rethiel i wetlands","vem är greenwarden"}},{q="Varifrån kommer alla orcher i träsket?",a="Orcherna tillhör Dragonmaw-klanen, som befäste sig i Grim Batol under andra kriget. Efter att den befriade röda drakflykten krossat deras styrkor flydde de överlevande orcherna ner i träsket och kullarna, där de fortfarande plundrar vägar och angriper resande.",al={"varför finns det orcher i wetlands","dragonmaw i wetlands","dragonmaw-klanen i wetlands"}}},fx={["2cd88152"]={q="Vad är Wetlands?",a="Wetlands är ett kallt och vidsträckt träskland mellan bergen i Khaz Modan och västerhavet. Regionen ligger insvept i ständigt grå dimma, strax norr om Loch Modan och söder om Arathi Highlands. En gång fanns här många dvärgbosättningar, men tidigare krig har ödelagt området. Nu är det en karg och otämjd vildmark som skiljer dvärgkungadömena från ruinerna av Lordaeron.",al={"vad är wetlands","wetlands bakgrund","berätta om wetlands"}},["4984d286"]={q="Varför är det bara träsk här?",a="Wetlands ligger i en låg sänka som omges på tre sidor av höga bergskedjor och samlar upp avrinning från höjderna ovanför. Otaliga floder, dammar och bäckar rinner ner mot Baradin Bay och håller marken ständigt vattenmättad och kall.",al={"varför är wetlands ett träsk","wetlands geografi","varför så mycket vatten i wetlands"}},["60c5b961"]={q="Vilka bor i Wetlands?",a="Alliansens främsta fäste är Menethil Harbor, där dvärgbergsmän kämpar för att hålla viktiga utposter. Men fientliga krafter dominerar vildmarken: utstötta Dragonmaw-orcher gömmer sig i de östra bergssluttningarna, Mosshide-gnoller stryker omkring i kärren, murlocker kryper längs kusterna och våldsamma Dark Iron-dvärgar tränger söderut från Dun Modr.",al={"vilka bor här","fraktioner i wetlands","invånare i wetlands"}},["8d21dccb"]={q="Vad är Menethil Harbor, och vem styr där?",a="Menethil Harbor är en kraftigt befäst hamnstad på en ö i Baradin Bay, och Alliansens främsta kustport till Khaz Modan. Staden är uppkallad efter kung Terenas Menethil II av Lordaeron och sköts av dvärgar och allierade människor. Den skyddas av Menethil Keeps bastanta stenmurar och vaktas av Captain Stoutfists garnison.",al={"menethil harbor","vem styr menethil","menethil stad"}},fd9bb568={q="Varför byggde dvärgarna en hamn här?",a="Under det andra kriget byggde Orgrim Doomhammer ett skeppsvarv här för att föra horden över Baradin Bay till Lordaeron. När orcherna hade drivits bort återtog Alliansen platsen och byggde om den till en blomstrande hamn. Därifrån kunde viktiga sjövägar förnödenheter föra mellan Khaz Modan, mänskliga allierade och avlägsna länder på andra sidan havet.",al={"varför menethil harbor","varför bygga en hamn i träsket","skälet till menethil harbor"}},["4cff40a7"]={q="Tillhör Menethil Harbor Alliansen?",a="Ja. Menethil Harbor är ett officiellt fäste för Alliansen. Det är en rå och livlig hamnstad full av sjömän, köpmän, resenärer och hårdföra hamnarbetare, men där vajar Alliansens baner och Ironforge-styrkor försvarar staden.",al={"tillhör menethil alliansen","menethil harbor fraktion","vem äger menethil harbor"}},["6dc9c02b"]={q="Vem bestämmer här omkring?",a="Det finns ingen ensam härskare över det otämjda träsklandet. Alliansens makt är samlad i Menethil Harbor, under Captain Stoutfist och garnisonen i Menethil Keep. Utanför hamnens murar är träsket en laglös gränsbygd som militära patruller, orchkrigsherrar och urtidsbestar kämpar om.",al={"vem leder wetlands","befälhavare i wetlands","vem bestämmer här"}},b8a9f96f={q="Vem är Captain Stoutfist?",a="Captain Stoutfist är dvärgarnas befälhavare för garnisonen i Menethil Harbor. Från hamnens trygghet samordnar han försvaret av träsket och ger dugliga äventyrare i uppdrag att hejda de oupphörliga räderna från de närliggande Dragonmaw-orcherna.",al={"captain stoutfist wetlands","stoutfist bakgrund","vem är stoutfist"}},["38351a9f"]={q="Vilka är Dragonmaw-orcherna, och varför är de här?",a="Dragonmaw är en brutal orchklan som använde Demon Soul för att förslava Alexstrasza och den röda drakflykten under det andra kriget. De härskade från Grim Batols höjder. När drakdrottningen befriades krossade de hämndlystna drakarna klanen och skingrade de överlevande i Wetlands träsk och berg. Där utgör de fortfarande ett våldsamt och ihållande hot.",al={"dragonmaw wetlands","varför är dragonmaw i wetlands","dragonmaw-orcher"}},ecc875bb={q="Vilka är Dark Iron-dvärgarna, och varför anfaller de Dun Modr?",a="Dark Iron är en förrädisk dvärgklan som länge varit landsförvisad från Ironforge och behärskar skuggmagi. När Alliansens styrkor skickades utomlands passade de på att slå till norrut, inta staden Dun Modr och sabotera Thandol Span. På så vis ville de kapa viktiga förbindelser och återta mark i Khaz Modan.",al={"dark iron dun modr","varför är dark iron i wetlands","dark iron anfaller wetlands"}},["0f0d7fa8"]={q="Vad är Thandol Span, och varför är det viktigt?",a="Thandol Span är ett magnifikt par väldiga stenbroar som dvärgar byggt över klyftan mellan norra Khaz Modan och Arathi Highlands. De byggdes efter de tre hammarna krig för att främja handel och gemenskap med Wildhammers. Än i dag är de den enda landförbindelsen mellan de södra kungadömena och norra Lordaeron.",al={"thandol span","thandol-bron","varför är thandol span viktigt"}},faff9f74={q="Varför vill Dark Iron spränga bron?",a="Genom att förstöra Thandol Span vill Dark Iron isolera Ironforge och Khaz Modan helt från Alliansens allierade i Lordaeron. Om livlinan över land kapas kan inga förstärkningar marschera söderut för att återta Dun Modr eller hjälpa till mot fler angrepp från Dark Iron.",al={"varför förstöra thandol span","dark irons broplan","spränga thandol span"}},eabba297={q="Hur hamnade jag i Wetlands, och vart leder vägen härifrån?",a="De flesta resenärer kommer norrut från Loch Modan genom bergspasset Dun Algaz, eller tar den långa båtresan till Menethil Harbor. Härifrån fortsätter vägen norrut över Thandol Span till Arathi Highlands, medan fartyg från hamnen för äventyrare västerut över Stora havet.",al={"vart ska man ta vägen från wetlands","nästa område efter wetlands","väg genom wetlands"}},["75fb0ece"]={q="Är det här vägen till Ironforge?",a="Ja. Följ vägen söderut ut ur träsket så kommer du rakt in i Dun Algaz smala tunnlar. Genom bergen når du Loch Modan. Därifrån går huvudvägen västerut genom North Gate Pass, direkt in i Dun Moroghs snö och vidare till Ironforge.",al={"vägen till ironforge från wetlands","hur tar jag mig till ironforge från wetlands","vägen till ironforge"}},["78aee5e0"]={q="Hur hamnade jag i Wetlands?",a="De flesta alliansresenärer når Wetlands genom att färdas norrut från Loch Modan och ta sig genom Dun Algaz smala bergstunnlar ner till de dimmiga kärren. Andra kommer med skepp över Stora havet och seglar från Kalimdors stränder till Menethil Harbor. De som färdas söderut från Arathi Highlands måste i stället ta sig över de farliga övergångarna på det förstörda Thandol Span.",al={"hur hamnade jag här","hur kom jag till wetlands","var kom jag ifrån"}},["87ca94d2"]={q="Vad förväntas jag göra i Wetlands?",a="Träsket är en hårt ansatt gränsbygd där Alliansen klamrar sig fast vid ett bräckligt fäste. Från Menethil Harbor ska du skydda viktiga handelsvägar och slå tillbaka de Dragonmaw-orcher som fortfarande härjar i låglandet. Längre österut och norrut behöver dvärgbergsmän din hjälp att hålla fientliga gnollflockar stången, bistå utsatta utgrävningsplatser och driva tillbaka Dark Iron-dvärgarna som hotar att helt kapa Thandol Span.",al={"vad ska jag göra här","varför är jag här","vad är mitt uppdrag i wetlands"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Winterspring",s="Winterspring är en vidsträckt, snötäckt dal högt uppe på Mount Hyjals nordöstra sluttningar, precis ovanför Moonglades och Felwoods förtrollade skogar. Regionen är känd för sin bitande kyla, sina urgamla Highborne-ruiner och kringströvande toppredatorer, och kretsar kring den neutrala goblinutposten Everlook. Här finns fortfarande hårda naturfaror och rester av den blå drakflygeln, samtidigt som dalen bekämpar demonisk korruption längs de södra höjderna.",h="Winterspring är en vidsträckt, snötäckt dal högt uppe på Mount Hyjals nordöstra sluttningar, precis ovanför...",kw={"blå drakar","darkwhisper gorge","donova snowden","everlook","frostsaber","icecap","kel'theril","mazthoril","timbermaw","winterspring"},ang={["class:Druid"]="Högt ovanför Moonglade ligger Winterspring, en plats av helig betydelse där Malfurion Stormrage väckte Druids of the Talon ur deras uråldriga sömn under Tredje kriget.",["faction:Alliance"]="Alliansens hjältar besöker ofta Rivern Frostwind vid Frostsaber Rock. De arbetar oförtröttligt i den extrema kylan för att vinna de ansedda Winterspring Frostsaber-ridbestarnas lojalitet.",["profession:Herbalism"]="Winterspring är den enda kända växtplatsen för Icecap, en oumbärlig alpört som är mycket eftertraktad för avancerade alkemiska brygder. Här finns också spridda Mountain Silversage och sällsynta Black Lotus-blommor.",["profession:Mining"]="De isiga klipporna och grottväggarna i dalen är rika på värdefulla mineraler. Där hittar man ofta små och rika thoriumådror samt sällsynta fyndigheter av äkta silver.",["race:NightElf"]="Winterspring är nära knutet till alvernas historia. Här finns gravkamrarna där Druids of the Talon vilade i årtusenden, de tragiska ruinerna av Kel'Theril och blottlagda rötter från Nordrassil som skadades under slaget vid Mount Hyjal."},sec={{t="Ett rike av ständig frost",b="Winterspring ligger tusentals fot över den omgivande vildmarken, under klar bergsluft och obevekliga snöstormar. Enorma, blottlagda rötter från världsträdet Nordrassil skär genom snödrivorna som väldiga trävalv, förvridna under Tredje krigets avgörande strider. Medan stora delar av norra Kalimdor domineras av täta skogar och varmt klimat, är Winterspring ett stilla land med medelhöga alpina skogar, klippiga branter och frusna sjöar, där väldiga frostsablar, chimärer, yetier och tjockpälsade vinterbjörnar håller till."},{t="Vägar och utposter",b="För att nå denna höga platå måste du ta dig genom Timbermaw Holds urgamla, uthuggna passager. De vaktas av okorrumperade furbolger som noggrant granskar alla resenärer från Felwood eller Moonglade. Mitt i dalen ligger Everlook, en blomstrande handelsstad som drivs av Steamwheedle Cartel. Gobliner välkomnar både alliansens och hordens äventyrare med öppna register och erbjuder en oumbärlig tillflykt med ingenjörskonst, handel och varma eldar mot den bitande bergskylan."},{t="Gamla spöken och blå drakar",b="Århundraden innan dagens bosättningar uppstod byggde forntida alver staden Kel'Theril vid sjön. Efter att vårdslösa Highborne-trollkarlar krossade den förbannade Crystal of Zin-Malor greps de av vansinne, och rastlösa vålnader har vandrat bland de förstörda pelarna och det frusna vattnet ända sedan dess. Längre söderut reser sig Mazthorils grottiga höjder, den blå drakflygelns traditionella fäste i Kalimdor. Här vakar Spell-Weaver Malygos avkomma över de arkaniska strömmarna under beskydd av matriarken Haleh och bemöter lokala hot."},{t="Den hotande skuggan över ravinen",b="Wintersprings frid bryts tvärt vid den sydligaste gränsen, i Darkwhisper Gorge. Där krälar elitstyrkor av demoner, kvarlevor från Tredje krigets legioner, genom branta raviner som blockerar de höga vägarna mot Mount Hyjals topp. Samtidigt har de inhemska Winterfall-furbolgerna fallit offer för vidrig korruption, vilket fått oberoende forskare som Donova Snowden att undersöka den framryckande smittan innan hela dalens djurliv slukas."}},faq={{q="Hur tar jag mig till Winterspring?",a="Resenärer måste ta sig genom Timbermaw Hold, ett underjordiskt tunnelsystem i nordöstra Felwood. För att färdas fredligt genom grottorna måste du vinna de lokala Timbermaw-furbolgernas förtroende. De anfaller alla inkräktare som de anser vara fientliga. När du kommit ut genom den östra utgången breder Wintersprings snötäckta sluttningar genast ut sig framför dig.",al={"ta sig till winterspring","komma in i winterspring","ingång till winterspring","timbermaw-tunneln till winterspring"}},{q="Vem styr staden Everlook?",a="Everlook sköts av Steamwheedle Cartel, goblinernas handelskoalition. Tack vare goblinernas strikta vinstintresse och neutralitet kan både hordens och alliansens resenärer besöka stadens flygmästare, reparationsförsäljare, bankvalv och handelsstånd, så länge de inte stör freden innanför stadsgränsen.",al={"vem styr everlook","everlooks fraktion","är everlook neutralt"}},{q="Vilka är spökena som hemsöker Lake Kel'Theril?",a="De är andar efter Highborne-nattalver som bodde i den forntida staden Kel'Theril för tiotusen år sedan. När deras trollkarlar manipulerade den stulna Crystal of Zin-Malor utlöste dess krossande en katastrofal förbannelse. Århundraden senare drabbades även expeditioner av högalver av vansinne och dömdes att hemsöka de frusna ruinerna tillsammans med sina förfäder.",al={"spöken vid lake kel'theril","andar i ruinerna av kel'theril","vilka finns vid kel'theril"}},{q="Varför är Winterfall-furbolgerna aggressiva?",a="Winterfall-furbolgerna har dukat under för en spridande, onaturlig korruption som drivit klanen till vansinnigt raseri. Medan närliggande Timbermaw håller fast vid sitt förstånd har Winterfall fallit under mörka influenser. Det har fått forskare som Donova Snowden att studera smittan och rensa deras läger.",al={"varför är winterfall fientliga","winterfall-stammens korruption","donova snowden och furbolgerna"}},{q="Vad lever inne i Mazthoril?",a="Mazthoril är den blå drakflygelns främsta boplats och fristad i Kalimdor. Djupt inne i dess grottiga spiror vaktar wyrmkin, elitsyngel och uråldriga drakar mäktiga drakreliker och arkaniska hemligheter under den vakande blicken från Haleh, Malygos gemål.",al={"drakar i mazthoril","vad är mazthoril","blå drakar i winterspring"}},{q="Vad är Darkwhisper Gorge?",a="Darkwhisper Gorge är en förrädisk ravin längst söderut i dalen, där mäktiga elitdemoner från Tredje kriget håller till. Den fungerar som en hårt bevakad gräns längs de förrädiska stigarna som leder mot Mount Hyjals höjder.",al={"demoner i darkwhisper gorge","vad finns i darkwhisper gorge","hyjals port vid winterspring"}},{q="Kan jag träna eller tämja frostsablar här?",a="Längst norrut i dalen tar nattalven Rivern Frostwind hand om de inhemska vita katterna vid Frostsaber Rock. Äventyrare som hjälper honom att säkra förnödenheter och skydda flocken kan visa sig värdiga att lära sig hemligheterna bakom att föda upp och rida på en Frostsaber.",al={"frostsaber-riddjur","rivern frostwind och frostsaber","skaffa en frostsaber"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Zephras Isle",s="Zephras Isle är en svävande ö i Skywall, luftens elementarplan. Den är Skybornes urgamla hem, men deras samhälle står nu inför en existentiell kris när öns bärande magi långsamt försvagas. Kontakten med de närliggande himmelrikena har brutits, och invånarna kämpar mot elementarisk kollaps och flyktingar som anländer.",h="Zephras Isle är en svävande ö i Skywall, luftens elementarplan.",kw={"luftskepp","anvilas","elementarplan","siroccas","skyborne","skywall","valanaar","vindstenar","zephras"},ang={["class:Shaman"]="Zephras Isle ligger mitt i luftens elementarplan och visar vad som händer med elementära länder när andarna som håller dem i balans plötsligt försvinner.",["race:Skyborne"]="Zephras Isle är ditt förfädershem och din startplats, men öns kvarvarande skönhet döljer en akut kris med mark som faller sönder och elementarkraft som bleknar."},sec={{t="Ett rike i skyn",b="Zephras Isle är en isolerad landmassa som driver genom Skywalls ändlösa vindar. I generationer levde Skyborne här tillsammans med inhemska luftelementaler, som hjälpte till att bevara de magiska strömmar som höll ön svävande. Men för flera århundraden sedan försvann dessa elementarväktare helt. Utan deras närvaro och beskydd har de dolda förtrollningar som håller uppe landet långsamt börjat svikta, vilket får Zephras att spricka och bli allt mer instabil."},{t="Avskurna horisonter",b="Zephras var inte den enda tillflyktsorten för Skyborne på elementarplanet. Systeröarna Anvilas och Siroccas drev också genom Skywall, men kontakten mellan dem upphörde efter att elementalerna försvann. På senare tid har flyktingar från dessa sönderfallande grannöar lyckats ta sig till Zephras i jakt på trygghet. De för med sig dystra nyheter: de andra öarna faller sönder under deras fötter."},{t="Tröskeln till Azeroth",b="När deras egen landmassa långsamt vittrar sönder har Skyborne på Zephras börjat blicka bortom Skywalls gränser, mot Azeroth. Från Valanaars luftskeppshamnar ger sig luftskepp nu av för att upprätta sällsynta livlinor till de dödligas värld. Resorna förbinder luftdomänen direkt med platser på Azeroth, däribland utkanten av Dalaran i Alterac Mountains och Skywatcher Plateau i Mulgore."}},faq={{q="Var ligger Zephras Isle?",a="Zephras Isle ligger inne i Skywall, luftens elementarplan, och inte på Azeroths yta. Ön svävar bland de eviga molnen och vindströmmarna i detta eteriska rike.",al={"zephras isle läge","var ligger zephras","vilket plan ligger zephras på"}},{q="Varför faller Zephras Isle sönder?",a="Ön var beroende av de inhemska luftelementaler som en gång levde sida vid sida med Skyborne. För flera århundraden sedan försvann dessa elementaler, och de magiska grundvalar som förankrar och bevarar den flygande ön har sedan dess långsamt försvagats och vittrat sönder.",al={"varför kollapsar zephras","zephras isle förstörelse","döende ö"}},{q="Vad är Anvilas och Siroccas?",a="Det är närliggande flytande öar i Skywall där Skyborne också bor. Zephras Isle förlorade kontakten med båda när elementalerna försvann, och flyende flyktingar rapporterar nu att både Anvilas och Siroccas håller på att störta i avgrunden.",al={"anvilas","siroccas","andra skyborne-öar"}},{q="Hur tar man sig mellan Zephras Isle och Azeroth?",a="Skyborne driver luftskeppshamnar vid bosättningen Valanaar. Därifrån lyfter luftskepp och färdas över plangränsen till Azeroth, där de landar nära Dalaran i Alterac Mountains och vid Skywatcher Plateau i Mulgore.",al={"hur lämnar man zephras","zephras luftskepp","resa till azeroth"}},{q="Vilka är Skyborne?",a="Skyborne är invånarna som har sitt hem på Zephras Isle och dess systerriken i skyn. De har levt i Skywall i generationer och står nu inför förstörelsen av sitt flygande hemland när dess bindande magi bleknar.",al={"skyborne-folket","vem bor på zephras"}},{q="Vilka bor på Zephras Isle förutom Skyborne?",a="Förutom fridfulla byar och besökande flyktingar plågas ön av lokala banditer, nattklor som lever i grottor och vidunder i områden som Shriekling Den och Nightclaw Cavern.",al={"zephras invånare","fiender på zephras"}}},fx={b4875d06={q="Var ligger ön i förhållande till resten av Azeroth?",a="Zephras Isle ligger inte på Azeroths yta. Den driver genom Skywall, en separat dimensionell domän som titanernas skapelser utformade för att hålla kaotiska luftelementaler instängda. De enda fysiska förbindelserna mellan ön och den dödliga världen nedanför är särskilda luftskepp som lägger till vid Valanaar och färdas över gränsen till platser som Dalaran och Mulgore.",al={"var ligger zephras i förhållande till azeroth","ligger zephras i azeroth","zephras läge i förhållande till azeroth"}},["2c89f95d"]={q="Vilka är Al'Aketh?",a="Al'Aketh är en av fraktionerna som tävlar om herraväldet på Zephras Isle, tillsammans med The High Order och The Windshapers. När pylonerna som håller ön på plats sviktar och kampen för överlevnad blir allt mer desperat, kämpar Al'Aketh aktivt om överhöghet och kontroll över öns återstående mystiska resurser.",al={"vad är al'aketh","al'aketh-fraktionen","vilka är al'aketh"}},["6e14d755"]={q="Kommer jag så småningom att lämna ön?",a="Ja. Zephras Isle är ditt hem och din första träningsplats, men luftskepp lämnar skydockorna vid Valanaar och färdas genom planära rämnor till Azeroths fastland. De går direkt till Dalaran i Alterac Mountains och Skywatcher Plateau i Mulgore.",al={"kommer jag att lämna zephras","lämna zephras isle","kan vi ta oss till azeroth"}},["19470e71"]={q="Hur hamnade jag på Zephras Isle?",a="Du föddes bland Skyborne, shen'dorei som bor på denna svävande fristad högt uppe i Skywall, luftens elementarplan. För årtusenden sedan flydde dina förfäder från prins Tortheldrins utrensning i Eldre'Thalas och slöt en pakt med vindandar som lyfte denna fristad mot himlen. Medan andra systeröar som Anvilas och Siroccas faller sönder eller försvinner utom räckhåll, har Zephras Isle varit ditt hem sedan födseln. Här börjar du din resa bland ditt eget folk.",al={"hur hamnade jag här","hur tog jag mig till zephras isle","varför vaknade jag här","var kom jag ifrån"}},["5dae6f41"]={q="Vad förväntas jag göra på Zephras Isle?",a="Ditt hem rasar samman under dina fötter. För flera århundraden sedan försvann de välvilliga luftelementalerna, och de arkana pylonerna som håller Zephras Isle samman förlorar sin kraft. Flyktingar strömmar in från yttre öar som håller på att rasa samman, medan rivaliserande fraktioner, däribland The High Order, The Windshapers och Al'Aketh, grälar om det som återstår. Du måste hjälpa ditt folk, kuva inre hot och vilda bestar, hjälpa till att stabilisera den sviktande magin och till sist söka en väg ner till Azeroth innan ön faller.",al={"vad borde jag göra här","vad är mitt mål här","vad gör jag på zephras isle","varför är jag här"}},["1fd88046"]={q="Vad är Zephras Isle?",a="Zephras Isle är en svävande landmassa högt uppe i Skywall, luftens elementplan. För tusentals år sedan förhandlade nattalver som flydde förföljelse i Eldre'Thalas med de inhemska vindandarna. Andarna lyfte ön mot himlen för att hålla dem trygga. Ön är deras ättlingars, Skybornes, förfäders fristad.",al={"vad är zephras","om zephras isle","information om zephras isle"}},["7ea7c85c"]={q="Vad hände på Zephras Isle?",a="Zephras Isle lyftes upp till Skywall efter att högborne förfäder bröt sig loss från prins Tortheldrins blodiga styre i Eldre'Thalas. Skyborne levde i harmoni med luftens elementarer i tusentals år, men för flera hundra år sedan försvann deras elementära beskyddare utan förklaring. Utan deras ständiga magi började pelarna som förankrar ön förfalla. Flyktingar från närliggande öar som håller på att falla sönder har sökt sig hit, samtidigt som interna fraktioner kämpar om de sinande resurserna.",al={"zephras historia","vad hände här på zephras","zephras bakgrund"}},["70a3c6ae"]={q="Är Zephras Isle farligt?",a="Ja. Ön håller själv på att bli instabil och störta från himlen, och när de elementära beskyddarna försvann lämnades landet i kaos. Banditläger, bon av fientliga vilddjur och en våldsam politisk konflikt mellan The High Order, Windshapers och Al'Aketh gör det farligt att färdas utanför de befästa bosättningarna.",al={"är zephras farligt","hot på zephras","faror på zephras"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
